export interface TemplateSourceOptions {
  readonly baseURL: string;
  readonly ancestors?: readonly string[];
  readonly signal?: AbortSignal;
}

export interface TemplateSource {
  readonly url: string;
  readonly requestedURL: string;
  readonly html: string;
  /** 包含本次请求与重定向最终地址，供子片段检测别名循环。 */
  readonly ancestors: readonly string[];
}

interface SourceLocation {
  readonly src: string;
  readonly baseURL?: string;
  readonly requestedURL?: string;
  readonly finalURL?: string;
  readonly ancestors: readonly string[];
}

/** 保留声明位置、已知加载链以及原始异常；取消原因也保持原值。 */
export class TemplateSourceError extends Error implements SourceLocation {
  readonly src: string;
  readonly baseURL?: string;
  readonly requestedURL?: string;
  readonly finalURL?: string;
  readonly ancestors: readonly string[];

  constructor(location: SourceLocation, cause: unknown) {
    const chain = location.ancestors.length ? location.ancestors.join(' -> ') : '(unresolved)';
    super(`Failed to load Template ${JSON.stringify(location.src)} from ${JSON.stringify(location.baseURL)}; chain: ${chain}`, { cause });
    this.name = 'TemplateSourceError';
    this.src = location.src;
    this.baseURL = location.baseURL;
    this.requestedURL = location.requestedURL;
    this.finalURL = location.finalURL;
    this.ancestors = Object.freeze([...location.ancestors]);
  }
}

function resourceURL(reference: string, baseURL: string): string {
  const url = new URL(reference, baseURL);
  url.hash = '';
  return url.href;
}

/** 原生浏览器资源加载基础；无缓存，不解析 HTML、不初始化任何行为。 */
export async function loadTemplateSource(
  src: string,
  options: TemplateSourceOptions,
): Promise<TemplateSource> {
  let baseURL: string | undefined;
  let signal: AbortSignal | undefined;
  let requestedURL: string | undefined;
  let finalURL: string | undefined;
  let chain: string[] = [];
  try {
    baseURL = options?.baseURL;
    signal = options?.signal;
    // 先保存声明链，使入口取消或 URL 解析失败也能定位来源。
    chain = [...(options?.ancestors ?? [])];
    signal?.throwIfAborted();
    if (typeof src !== 'string' || !src.trim()) throw new TypeError('Template src must be a non-empty string');
    if (typeof baseURL !== 'string' || !baseURL.trim()) throw new TypeError('Template baseURL must be a non-empty URL');

    const resolutionBase = baseURL;
    const ancestors = chain.map(url => resourceURL(url, resolutionBase));
    requestedURL = resourceURL(src, resolutionBase);
    chain = [...ancestors, requestedURL];
    if (ancestors.includes(requestedURL)) throw new Error(`Circular Template include: ${requestedURL}`);

    const response = await fetch(requestedURL, { signal });
    signal?.throwIfAborted();
    // 网络响应提供最终 URL；空 URL 的合成响应沿用请求地址。
    finalURL = resourceURL(response.url || requestedURL, requestedURL);
    if (finalURL !== requestedURL) chain.push(finalURL);
    if (ancestors.includes(finalURL)) throw new Error(`Circular Template redirect: ${finalURL}`);
    if (!response.ok) throw new Error(`Template request failed: HTTP ${response.status} ${response.statusText}`.trim());

    const html = await response.text();
    signal?.throwIfAborted();
    return Object.freeze({
      url: finalURL,
      requestedURL,
      html,
      ancestors: Object.freeze([...chain]),
    });
  } catch (cause) {
    // 某些 fetch 实现会把取消转换为其他异常；保留调用方给出的真实取消原因。
    const failure = signal?.aborted ? signal.reason : cause;
    throw new TemplateSourceError({ src, baseURL, requestedURL, finalURL, ancestors: chain }, failure);
  }
}
