import { loadInlineFunction } from '../behavior/module.js';
import { validateAlias } from './binding/path.js';

export interface HandlerSource {
  readonly expression: string;
  readonly aliases: readonly string[];
}

export interface HandlerEnvironment {
  readonly state: object | undefined;
  readonly actions: object | undefined;
  readonly context: object;
  readonly properties: object;
  readonly attributes: object;
  readonly readAlias: (name: string) => unknown;
}

export interface HandlerInstance {
  readonly handler: (event: Event) => unknown;
  readonly update: () => void;
}

export type HandlerFactory = (index: number, environment: HandlerEnvironment) => HandlerInstance;

/** 一份模板生成一个工厂模块；行实例只创建闭包，不创建逐行 Blob 或改写业务表达式。 */
export function loadHandlerFactory(sources: readonly HandlerSource[], sourceURL: string): Promise<HandlerFactory> {
  if (!sources.length) return Promise.resolve(() => { throw new Error('No handler expressions in this template'); });
  const cases = sources.map(({ expression, aliases }, index) => {
    for (const name of aliases) validateAlias(name);
    const reads = aliases.map(name => `${name} = __nsEnvironment.readAlias(${JSON.stringify(name)})`).join(';\n');
    return `case ${index}: {
      const { state, actions, context, properties, attributes } = __nsEnvironment;
      ${aliases.length ? `let ${aliases.join(', ')};` : ''}
      const __nsUpdate = () => { ${reads} };
      __nsUpdate();
      const __nsHandler = (\n${expression}\n);
      if (typeof __nsHandler !== 'function') {
        if (__nsHandler != null && (typeof __nsHandler === 'object')) __nsPromise.resolve(__nsHandler).catch(() => {});
        throw new TypeError('Event handler expression must produce a function (handler ${index + 1})');
      }
      return { handler: __nsHandler, update: __nsUpdate };
    }`;
  });
  const source = `const __nsPromise = Promise;
  export default function(__nsIndex, __nsEnvironment) {
    switch (__nsIndex) { ${cases.join('\n')} }
    throw new Error('Unknown template handler');
  }`;
  // 同一来源在不同 include 行作用域中拥有不同的变量声明，不能互相覆盖缓存。
  const label = new URL(sourceURL);
  label.hash = `handlers-${JSON.stringify(sources.map(item => item.aliases))}`;
  return loadInlineFunction<HandlerFactory>(source, label.href, 'event');
}
