/** 浏览器装配入口：注册宿主元素、连接加载上下文，并将导航交给逻辑路由组。 */
import { createBehaviorRegistry } from '../behavior/registry.js';
import type { Behavior } from '../behavior/types.js';
import { RouteGroup } from '../router/group.js';
import { ComponentController, loadComponentTemplate } from './host.js';
import type { ContentContext, ManagedResource } from './context.js';

const registry = createBehaviorRegistry();
/** 只登记业务定义；实例由模板绑定或 Behavior 首次消费时按名称取得。 */
export function registerBehavior(name: string, behavior: Behavior): void { registry.register(name, behavior); }

/** 组件宿主元素的公开类型；输入与组件公开动作通过该元素的普通成员访问。 */
export interface TemplateElement extends HTMLElement {
    readonly ready: Promise<void>;
}

/** 单个宿主的运行记录，与可复用的组件定义登记分开管理。 */
interface HostRecord {
    /** 管理内容加载的内部控制器；host 一词仅指对应的 HTMLElement。 */
    controller: ComponentController;
    /** 父模板预先传入的环境；入口 DOM 中的宿主按文档环境连接。 */
    context?: ContentContext;
    /** ns-route 在所属候选组中的登记句柄，普通组件没有此项。 */
    registration?: ManagedResource;
    connected: boolean;
    /** 父区域已退出，旧节点必须重新取得加载上下文才能再次连接。 */
    staleContext?: boolean;
    /** 同轮路由属性更新只安排一次重新登记。 */
    refreshQueued?: boolean;
}

/** 标签名固定关联一个模板 URL，并复用该名称正在进行的注册任务。 */
interface ComponentRegistration {
    url: string;
    promise: Promise<void>;
}

/** 安装完成后提供浏览器操作；模块可在没有 DOM 的环境中安全导入。 */
let browser: {
    navigate(url: string | URL, options?: { replace?: boolean }): void;
    createComponent(name: string, templateURL: string | URL): Promise<void>;
} | undefined;

/** 浏览器入口自动调用；Node 中导入状态和类型不会创建 DOM。 */
export function installRuntime(): void {
    if (browser || typeof window === 'undefined' || typeof customElements === 'undefined') return;
    // hostRecords 按宿主元素保存运行记录；componentRegistrations 按标签名保存注册记录。
    const hostRecords = new WeakMap<HTMLElement, HostRecord>();
    const componentRegistrations = new Map<string, ComponentRegistration>();
    const report = (element: HTMLElement, error: unknown) => {
        const event = new CustomEvent('ns-error', { detail: error, bubbles: true, composed: true, cancelable: true });
        // 卸载及迟到动作的错误仍须到达应用级监听器。
        const target = element.isConnected ? element : document.documentElement;
        // preventDefault 只接管默认错误报告，资源清理仍由原调用流程负责。
        if (target.dispatchEvent(event)) {
            if (typeof globalThis.reportError === 'function') globalThis.reportError(error);
            else console.error(error);
        }
    };
    // 文档入口共享顶层路由组；嵌套组件的环境由父模板显式传递。
    const rootGroup = new RouteGroup(0, 0, {}, () => new URL(location.href), error => report(document.documentElement, error));
    const rootContext = (): ContentContext => ({ baseURL: document.baseURI, ancestors: [], acquireBehavior: registry.acquire, group: rootGroup });
    const getHostRecord = (element: HTMLElement): HostRecord => {
        let entry = hostRecords.get(element);
        if (!entry) {
            entry = { controller: new ComponentController(element, prepareChild, report), connected: false };
            hostRecords.set(element, entry);
        }
        return entry;
    };
    const dispose = (entry: HostRecord) => {
        entry.connected = false;
        const registration = entry.registration;
        entry.registration = undefined;
        const failures: unknown[] = [];
        // 路由登记与内容资源均须释放，任一清理抛错都不能阻断另一项。
        for (const cleanup of [() => registration?.dispose(), () => entry.controller.dispose()]) {
            try { cleanup(); } catch (error) { failures.push(error); }
        }
        if (failures.length) throw new AggregateError(failures, 'Element cleanup failed');
    };
    /** 模板视图在节点连接前调用，建立环境关联并将子资源归属交给调用区域。 */
    function prepareChild(element: Element, context: ContentContext): ManagedResource | undefined {
        if (!(element instanceof HTMLElement)
            || !['ns-include', 'ns-route'].includes(element.localName) && !componentRegistrations.has(element.localName)) return;
        const entry = getHostRecord(element);
        entry.context = context;
        entry.staleContext = false;
        return {
            stopBindings: () => { entry.controller.stopBindings(); entry.registration?.stopBindings(); },
            // 即使节点后来移到别处，原区域退出时仍清理它；移动不会转移所有权。
            dispose: () => { entry.staleContext = true; entry.context = undefined; dispose(entry); },
        };
    }

    /** 普通组件立即加载；路由宿主只登记候选，命中后才加载内容。 */
    function connect(element: HTMLElement): void {
        const entry = getHostRecord(element);
        // ns-html 的数据内容不会再取得框架模板的执行权限。
        if (!entry.context && element.closest('[ns-html]')) return;
        if (entry.connected || !element.isConnected) return;
        // 不能将已失效的嵌套节点当作文档入口重新解释。
        if (entry.staleContext) throw new Error('A disposed nested template requires a new loading context');
        entry.connected = true;
        const context = entry.context ?? rootContext();
        if (element.localName !== 'ns-route') entry.controller.load(context, componentRegistrations.get(element.localName)?.url);
        else {
            try {
                if ([...element.childNodes].some(node => node.nodeType !== Node.COMMENT_NODE && (node.nodeType !== Node.TEXT_NODE || node.textContent?.trim()))) {
                    throw new Error('ns-route requires src; inline route contents are not supported');
                }
                entry.registration = context.group.register({
                    element, context, content: entry.controller, activate: next => entry.controller.load(next),
                });
            } catch (error) {
                // 声明错误保留为候选收集失败，阻止 index 把它当作普通未匹配。
                const failed = context.group.hold();
                failed.fail();
                entry.registration = { stopBindings() {}, dispose: failed.release };
                throw error;
            }
        }
    }

    /** 具名标签、include 与 route 共用宿主连接及断开规则。 */
    class TemplateHostElement extends HTMLElement implements TemplateElement {
        constructor() { super(); if (!this.shadowRoot) this.attachShadow({ mode: 'open' }); getHostRecord(this); }
        get ready(): Promise<void> { return getHostRecord(this).controller.ready; }
        connectedCallback(): void {
            try {
                connect(this);
            } catch (error) { report(this, error); }
        }
        disconnectedCallback(): void {
            // 同轮移除再插入不重建实例；父区域的独立清理仍按原所有权执行。
            queueMicrotask(() => { if (!this.isConnected) { try { dispose(getHostRecord(this)); } catch (error) { report(this, error); } } });
        }
    }

    /** include 的 src 选择当前定义；route 复用此入口并增加候选声明字段。 */
    class IncludeElement extends TemplateHostElement {
        static observedAttributes = ['src'];
        attributeChangedCallback(_name: string, previous: string | null, next: string | null): void {
            if (previous === next || !getHostRecord(this).connected) return;
            if (this.localName === 'ns-route') {
                const entry = getHostRecord(this);
                if (entry.refreshQueued) return;
                entry.refreshQueued = true;
                // 合并 src/path/index 的同轮写入，重登完成前暂停候选选择。
                const hold = (entry.context ?? rootContext()).group.hold();
                queueMicrotask(() => {
                    entry.refreshQueued = false;
                    try {
                        if (!entry.connected || !this.isConnected) return;
                        try { dispose(entry); } catch (error) { report(this, error); }
                        try { connect(this); } catch (error) { report(this, error); }
                    } finally { hold.release(); }
                });
                return;
            }
            try { dispose(getHostRecord(this)); } catch (error) { report(this, error); }
            try { connect(this); } catch (error) { report(this, error); }
        }
    }
    class RouteElement extends IncludeElement {
        static observedAttributes = ['src', 'path', 'index'];
    }

    browser = {
        createComponent(name, templateURL) {
            const reserved = ['annotation-xml', 'color-profile', 'font-face', 'font-face-src', 'font-face-uri', 'font-face-format', 'font-face-name', 'missing-glyph'];
            if (typeof name !== 'string' || !/^[a-z][.0-9_a-z-]*-[.0-9_a-z-]*$/.test(name)
                || name.startsWith('ns-') || reserved.includes(name)) {
                return Promise.reject(new TypeError('Component name must be a lowercase ASCII custom element name outside the ns- namespace'));
            }
            if (!(typeof templateURL === 'string' && templateURL.trim()) && !(templateURL instanceof URL)) {
                return Promise.reject(new TypeError('Component template URL must be a non-empty string or URL'));
            }
            const reference = new URL(templateURL, document.baseURI);
            reference.hash = '';
            const url = reference.href;

            // 同名同地址共用注册 Promise；同名不同地址拒绝改变既有关联。
            const current = componentRegistrations.get(name);
            if (current) {
                return current.url === url ? current.promise
                    : Promise.reject(new Error(`Component ${name} is already registered with ${current.url}`));
            }
            if (customElements.get(name)) return Promise.reject(new Error(`Custom element already registered: ${name}`));
            const entry: ComponentRegistration = { url, promise: Promise.resolve() };
            componentRegistrations.set(name, entry);
            entry.promise = (async () => {
                // 先验证定义与公开字段，再注册元素，避免升级出半准备的实例。
                await loadComponentTemplate(url);
                // 每个名称必须使用独立 constructor；定义加载成功后才升级现有元素。
                customElements.define(name, class extends TemplateHostElement {});
            })().catch(cause => {
                // 失败登记允许重试，保留原始异常作为 cause。
                if (componentRegistrations.get(name) === entry) componentRegistrations.delete(name);
                throw new Error(`Failed to define component ${name} from ${url}`, { cause });
            });
            return entry.promise;
        },
        navigate(reference, options = {}) {
            const url = new URL(reference, location.href);
            if (url.origin !== location.origin) throw new Error('navigate requires a same-origin URL');
            // History API 不触发 popstate，因此这里主动安排路由重新匹配。
            if (options.replace) history.replaceState(null, '', url);
            else history.pushState(null, '', url);
            rootGroup.schedule();
        },
    };
    window.addEventListener('popstate', () => rootGroup.schedule());
    window.addEventListener('hashchange', () => rootGroup.schedule());
    document.addEventListener('click', event => {
        if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
        // 从组合路径寻找链接，使 ShadowRoot 内部的普通链接也能参与导航。
        const anchor = event.composedPath().find(node => node instanceof HTMLAnchorElement) as HTMLAnchorElement | undefined;
        if (!anchor || !anchor.hasAttribute('href') || anchor.hasAttribute('target') || anchor.hasAttribute('download')) return;
        const url = new URL(anchor.href);
        if (url.origin !== location.origin || !['http:', 'https:'].includes(url.protocol)) return;
        event.preventDefault();
        browser!.navigate(url);
    });
    // HTML 尚未解析完成时延后首轮选路，避免后出现的候选被遗漏。
    const initial = document.readyState === 'loading' ? rootGroup.hold() : undefined;
    if (initial) document.addEventListener('DOMContentLoaded', () => initial.settle(), { once: true });
    for (const [name, definition] of [['ns-include', IncludeElement], ['ns-route', RouteElement]] as const) {
        if (customElements.get(name)) throw new Error(`Custom element already registered: ${name}`);
        customElements.define(name, definition);
    }
    rootGroup.schedule();
}

/** 同源 History 导航；具体页面激活与保留规则由 RouteGroup 处理。 */
export function navigate(url: string | URL, options?: { replace?: boolean }): void {
    installRuntime();
    if (!browser) throw new Error('navigate is only available in a browser');
    browser.navigate(url, options);
}

/** 准备 HTML 定义并注册标准自定义元素；完成不代表任何具体宿主已经加载。 */
export async function createComponent(name: string, templateURL: string | URL): Promise<void> {
    installRuntime();
    if (!browser) throw new Error('createComponent is only available in a browser');
    return browser.createComponent(name, templateURL);
}

// 浏览器导入即安装基础宿主；无 DOM 环境由 installRuntime 的守卫直接返回。
installRuntime();
