/** 值绑定只解析路径；事件中的 JavaScript 由独立模块处理。 */
export interface ValuePath {
  readonly root: 'local' | 'business' | 'properties' | 'attributes' | 'alias';
  readonly name?: string;
  readonly path: readonly string[];
}

export interface HandlerPath {
  readonly name: string;
  readonly behavior?: string;
}

const identifier = /^[A-Za-z_$][\w$]*$/;
const segment = /^(?:[A-Za-z_$][\w$]*|\d+)$/;
export const unsafeNames = new Set(['__proto__', 'constructor', 'prototype']);

/** 直接动作路径不需要生成模块，其余 handler 表达式交给原生 ESM。 */
export function parseHandlerPath(expression: string): HandlerPath | undefined {
  if (typeof expression !== 'string') throw new TypeError('Handler expression must be a string');
  const match = /^(?:actions|context\.behaviors\.([A-Za-z_$][\w$]*)\.actions)\.([A-Za-z_$][\w$]*)$/.exec(expression.trim());
  if (!match) return;
  if (unsafeNames.has(match[1]) || unsafeNames.has(match[2])) throw new Error(`Invalid handler path: ${expression}`);
  return { name: match[2], ...(match[1] === undefined ? {} : { behavior: match[1] }) };
}
const reservedAliases = new Set((
  'state actions properties attributes context event arguments eval await yield let const var function class return ' +
  'if else for while do switch case default break continue try catch finally throw new delete ' +
  'typeof void in instanceof this super import export extends static enum implements interface ' +
  'package private protected public null true false with debugger'
).split(' '));

export function validateAlias(name: string): void {
  if (!identifier.test(name) || name.startsWith('__ns') || unsafeNames.has(name) || reservedAliases.has(name)) {
    throw new Error(`Invalid template alias: ${name}`);
  }
}

export function parseValuePath(expression: string, aliases: ReadonlySet<string> = new Set()): ValuePath {
  if (typeof expression !== 'string') throw new TypeError('Binding expression must be a string');
  const parts = expression.trim().split('.');
  const invalid = () => new Error(`Invalid value binding path: ${expression}`);
  if (!parts.length || parts.some(part => !segment.test(part) || unsafeNames.has(part))) throw invalid();
  const first = parts[0];
  if (first === 'state') return { root: 'local', path: parts.slice(1) };
  if (first === 'properties' || first === 'attributes') return { root: first, path: parts.slice(1) };
  if (first === 'context') {
    if (parts[1] === 'behaviors' && identifier.test(parts[2] ?? '') && parts[3] === 'state') {
      return { root: 'business', name: parts[2], path: parts.slice(4) };
    }
    throw invalid();
  }
  if (aliases.has(first)) return { root: 'alias', name: first, path: parts.slice(1) };
  throw invalid();
}

export function readOwnPath(root: unknown, path: readonly string[]): unknown {
  let value = root;
  for (const key of path) {
    if (value == null || !Object.hasOwn(Object(value), key)) return undefined;
    value = (value as Record<string, unknown>)[key];
  }
  return value;
}

/** 每次回写重新取得父对象，避免列表替换或父字段替换后写入旧引用。 */
export function writeOwnPath(root: unknown, path: readonly string[], value: unknown): void {
  if (!path.length || path.some(key => unsafeNames.has(key))) throw new Error('Model requires a writable field path');
  const parent = readOwnPath(root, path.slice(0, -1));
  if (parent === null || (typeof parent !== 'object' && typeof parent !== 'function')) {
    throw new TypeError('Model cannot write through a missing or non-object parent');
  }
  const key = path[path.length - 1];
  if (!Object.hasOwn(parent, key) && key in parent) throw new TypeError('Model cannot write an inherited property');
  if (Object.hasOwn(parent, key) && Object.is((parent as Record<string, unknown>)[key], value)) return;
  if (!Reflect.set(parent, key, value)) throw new TypeError('Model state field is not writable');
}

export interface ForeachDeclaration {
  readonly alias: string;
  readonly source: ValuePath;
  readonly key: ValuePath;
  readonly index?: string;
}

export function parseForeach(
  expression: string,
  key: string | null,
  index: string | null,
  aliases: ReadonlySet<string> = new Set(),
): ForeachDeclaration {
  const match = /^\s*([A-Za-z_$][\w$]*)\s+of\s+(.+?)\s*$/.exec(expression);
  if (!match) throw new Error(`Invalid ns-foreach declaration: ${expression}`);
  const alias = match[1];
  validateAlias(alias);
  const position = index?.trim();
  if (position !== undefined) validateAlias(position);
  if (position === alias) throw new Error('ns-index and ns-foreach aliases must differ');
  if (key === null || !key.trim()) throw new Error('ns-foreach requires ns-key');
  const source = parseValuePath(match[2], aliases);
  const rowAliases = new Set(aliases);
  rowAliases.add(alias);
  const identity = parseValuePath(key, rowAliases);
  if (identity.root !== 'alias' || identity.name !== alias) {
    throw new Error('ns-key must identify the current row, not its position or an outer value');
  }
  return { alias, source, key: identity, ...(position === undefined ? {} : { index: position }) };
}
