import { Signal, batch } from '../../state/signal.js';
import type { Scope } from '../../lifecycle/scope.js';

export interface ModelTarget {
  read(): unknown;
  write(value: unknown): void;
}

export interface ModelBinding {
  /** 控件接入实际树后关联原生 form；不建立公开的挂载生命周期 API。 */
  mount(): void;
}

type Kind = 'text' | 'number' | 'range' | 'checkbox' | 'radio' | 'select' | 'multiple';
const textual = new Set(['text', 'search', 'tel', 'url', 'email', 'password', 'date', 'datetime-local', 'month', 'week', 'time', 'color']);

interface ResetParticipant {
  capture(): (() => void) | undefined;
  report(error: unknown): void;
}
const resetForms = new WeakMap<HTMLFormElement, { members: Set<ResetParticipant>; listener: EventListener }>();

function watchReset(form: HTMLFormElement, participant: ResetParticipant): () => void {
  let group = resetForms.get(form);
  if (!group) {
    const members = new Set<ResetParticipant>();
    const listener = (event: Event) => queueMicrotask(() => {
      if (event.defaultPrevented) return;
      // 原生默认动作完成后先快照所有控件，再写状态；共享集合不能逐控件读写。
      const commits: { run: () => void; member: ResetParticipant }[] = [];
      for (const member of members) {
        try { const run = member.capture(); if (run) commits.push({ run, member }); }
        catch (error) { member.report(error); }
      }
      batch(() => {
        for (const { run, member } of commits) {
          try { run(); } catch (error) { member.report(error); }
        }
      });
    });
    group = { members, listener };
    resetForms.set(form, group);
    form.addEventListener('reset', listener);
  }
  group.members.add(participant);
  const current = group;
  return () => {
    current.members.delete(participant);
    if (!current.members.size) {
      form.removeEventListener('reset', current.listener);
      resetForms.delete(form);
    }
  };
}

/** ns-model 的原生控件协议。 */
export function bindModelTarget(
  element: Element,
  target: ModelTarget,
  scope: Scope,
  report: (error: unknown) => void,
  claim: (name: string) => void,
): ModelBinding {
  const input = element.localName === 'input' ? element as HTMLInputElement : undefined;
  const select = element.localName === 'select' ? element as HTMLSelectElement : undefined;
  const textarea = element.localName === 'textarea' ? element as HTMLTextAreaElement : undefined;
  const control = input ?? select ?? textarea;
  if (!control) throw new Error('ns-model requires a supported native form control');
  let active = true;
  let composing = false;
  let form: HTMLFormElement | null = null;
  let stopReset: (() => void) | undefined;

  const kind = (): Kind => {
    if (textarea) return 'text';
    if (select) return select.multiple ? 'multiple' : 'select';
    if (textual.has(input!.type)) return 'text';
    if (['checkbox', 'radio', 'number', 'range'].includes(input!.type)) return input!.type as Kind;
    throw new Error(`Unsupported ns-model input type: ${input!.type}`);
  };
  const strings = (value: unknown): readonly string[] => {
    if (!Array.isArray(value) || value.some(item => typeof item !== 'string')) {
      throw new TypeError('Selection collection model requires an array of strings');
    }
    return value;
  };
  const text = (value: unknown): string => {
    if (value == null) return '';
    if (typeof value === 'object' || typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError('Text model requires a scalar value');
    }
    return String(value);
  };
  const display = new Signal.Computed(() => {
    const value = target.read();
    // 集合成员参与依赖，数组原地增删也能更新勾选与多选，不要求应用替换数组。
    return Array.isArray(value) ? [...value] : value;
  });

  const apply = (value: unknown) => {
    const mode = kind();
    claim(mode === 'checkbox' || mode === 'radio' ? 'checked' : 'value');
    if (composing) return;
    if (mode === 'checkbox') {
      if (typeof value !== 'boolean' && !Array.isArray(value)) throw new TypeError('Checkbox model requires boolean or a string array');
      const checked = typeof value === 'boolean' ? value : strings(value).includes(input!.value);
      if (input!.checked !== checked) input!.checked = checked;
    } else if (mode === 'radio') {
      if (value != null && typeof value !== 'string') throw new TypeError('Radio model requires a string');
      const checked = value === input!.value;
      if (input!.checked !== checked) input!.checked = checked;
    } else if (mode === 'multiple') {
      const values = new Set(strings(value));
      for (const option of select!.options) {
        const selected = values.has(option.value);
        if (option.selected !== selected) option.selected = selected;
      }
    } else {
      if ((mode === 'number' || mode === 'range') && (value != null || mode === 'range')
        && (typeof value !== 'number' || !Number.isFinite(value))) {
        throw new TypeError(`${mode} model requires a finite number${mode === 'number' ? ' or null' : ''}`);
      }
      const next = text(value);
      if (control.value !== next) control.value = next;
    }
  };

  const capture = (resetting = false): (() => void) | undefined => {
    if (!active || composing) return;
    const mode = kind();
    const checked = input?.checked;
    const optionValue = input?.value;
    if (mode === 'radio' && !checked) {
      if (!resetting) return;
      const root = control.getRootNode() as Document | ShadowRoot;
      const selected = input!.name && [...root.querySelectorAll<HTMLInputElement>('input[type="radio"]')]
        .some(other => other.name === input!.name && other.form === input!.form && other.checked);
      if (selected) return;
      return () => { if (active) target.write(''); };
    }
    let value: unknown;
    if (mode === 'multiple') value = [...select!.selectedOptions].map(option => option.value);
    else if (mode === 'number' || mode === 'range') {
      if (input!.validity.badInput) return;
      value = input!.value === '' ? null : input!.valueAsNumber;
      if (typeof value === 'number' && !Number.isFinite(value)) return;
    } else value = control.value;
    return () => {
      if (!active) return;
      if (mode === 'checkbox') {
        const current = target.read();
        if (typeof current === 'boolean') target.write(checked);
        else {
          const values = strings(current);
          target.write(checked ? (values.includes(optionValue!) ? current : [...values, optionValue!])
            : values.filter(item => item !== optionValue));
        }
      } else target.write(value);
    };
  };
  const commit = () => {
    try { capture()?.(); } catch (error) { report(error); }
  };
  const mount = () => {
    if (!active || form === control.form) return;
    stopReset?.();
    form = control.form;
    stopReset = form ? watchReset(form, { capture() { composing = false; return capture(true); }, report }) : undefined;
  };
  const listen = (name: string, listener: EventListener) => {
    // 同一控件上的声明 capture handler 也能读取已提交的模型值。
    control.addEventListener(name, listener, true);
    scope.add(() => control.removeEventListener(name, listener, true));
  };
  scope.add(() => { active = false; stopReset?.(); stopReset = undefined; form = null; });
  scope.add(display.subscribe(apply));
  for (const name of ['input', 'change']) listen(name, event => {
    if ((event as InputEvent).isComposing) return;
    try {
      const mode = kind();
      const expected = ['checkbox', 'radio', 'select', 'multiple'].includes(mode) ? 'change' : 'input';
      if (name === expected) commit();
    } catch (error) { report(error); }
  });
  listen('compositionstart', () => { if (kind() === 'text') composing = true; });
  listen('compositionend', () => { if (composing) { composing = false; commit(); } });

  const observer = new MutationObserver(() => {
    if (!active) return;
    try { mount(); apply(display.get()); } catch (error) { report(error); }
  });
  observer.observe(element, {
    attributes: true, attributeFilter: ['type', 'multiple', 'value', 'form', 'selected'],
    ...(select ? { childList: true, subtree: true, characterData: true } : {}),
  });
  scope.add(() => observer.disconnect());
  return { mount };
}
