/** 组件模板顶层唯一的本地模块声明。 */
export interface InlineBehaviorDeclaration {
  readonly source: string;
  readonly sourceURL: string;
}

export interface ParsedTemplateFragment {
  readonly content: DocumentFragment;
  readonly sourceURL: string;
  readonly behavior?: InlineBehaviorDeclaration;
}

/** 惰性解析并先校验全部声明；模块导入和 Behavior 调用发生在此步骤之后。 */
export function parseTemplateFragment(html: string, sourceURL: string): ParsedTemplateFragment {
  if (typeof html !== 'string') throw new TypeError('Template source must be a string');
  const url = new URL(sourceURL).href;
  const template = document.createElement('template');
  template.innerHTML = html;
  const content = template.content;
  const scripts: HTMLScriptElement[] = [];
  const activeFragments: DocumentFragment[] = [];
  const collect = (fragment: DocumentFragment, active: boolean) => {
    if (active) activeFragments.push(fragment);
    for (const element of fragment.querySelectorAll<HTMLScriptElement | HTMLTemplateElement>('script[ns-behavior], template')) {
      if (element.localName === 'script') scripts.push(element as HTMLScriptElement);
      else {
        const structural = ['ns-foreach', 'ns-if', 'ns-else-if', 'ns-else'].some(name => element.hasAttribute(name));
        // 按文档顺序检查惰性内容中的声明，但不提前处理其资源或绑定。
        collect((element as HTMLTemplateElement).content, active && structural);
      }
    }
  };
  collect(content, true);
  let behavior: InlineBehaviorDeclaration | undefined;
  for (const [index, script] of scripts.entries()) {
    const label = new URL(url);
    label.hash = `behavior-${index + 1}`;
    if (script.parentNode !== content) throw new Error(`Local Behavior must be declared at component template top level: ${label.href}`);
    if (behavior) throw new Error(`Duplicate local Behavior: at most one declaration per component: ${label.href}`);
    if (script.getAttribute('type')?.trim().toLowerCase() !== 'module') throw new Error(`Local Behavior requires type="module": ${label.href}`);
    if (script.hasAttribute('src')) throw new Error(`Local Behavior must be inline: ${label.href}`);
    behavior = { source: script.textContent ?? '', sourceURL: label.href };
  }
  // HTML link 地址按模板来源解析；CSS 文本及普通惰性 template 保持原样。
  for (const link of activeFragments.flatMap(fragment => [...fragment.querySelectorAll('link[rel][href]')])) {
    if (link.getAttribute('rel')!.split(/\s+/).some(token => token.toLowerCase() === 'stylesheet')) {
      link.setAttribute('href', new URL(link.getAttribute('href')!, url).href);
    }
  }
  for (const script of scripts) script.remove();
  return { content, sourceURL: url, behavior };
}
