export interface RouteDeclaration {
  readonly path?: string;
  readonly index: boolean;
  readonly src: string;
}

export type RoutePathSegment =
  | { readonly kind: 'static'; readonly value: string }
  | { readonly kind: 'parameter'; readonly name: string };

export type ParsedRouteDeclaration =
  | { readonly kind: 'index'; readonly src: string }
  | { readonly kind: 'path'; readonly src: string; readonly segments: readonly RoutePathSegment[] };

export interface RoutePathMatch {
  readonly params: Readonly<Record<string, string>>;
  readonly consumed: number;
}

const parameterName = /^[$_\p{ID_Start}][$\u200C\u200D\p{ID_Continue}]*$/u;
const forbiddenNames = new Set(['__proto__', 'constructor', 'prototype']);

/** 校验单条声明；depth 来自逻辑路由关系，而不是 DOM 或 Template 的嵌套层数。 */
export function parseRouteDeclaration(declaration: RouteDeclaration, depth: number): ParsedRouteDeclaration {
  if (!Number.isInteger(depth) || depth < 0) throw new Error('Route depth must be a non-negative integer');
  if (!declaration || typeof declaration !== 'object') throw new TypeError('Route declaration must be an object');
  const { path, index, src } = declaration;
  if (typeof src !== 'string' || !src.trim()) throw new Error('Route src must be a non-empty string');
  if (typeof index !== 'boolean') throw new Error('Route index must be a boolean');
  if (index) {
    if (path !== undefined) throw new Error('Route path and index are mutually exclusive');
    return { kind: 'index', src: src.trim() };
  }
  if (typeof path !== 'string' || !path.trim()) throw new Error('Route path must be a non-empty string');

  const normalized = path.trim();
  if (/[?#*]/.test(normalized)) throw new Error('Route path does not support query, hash, wildcard or optional parameters');
  if (depth === 0 && !normalized.startsWith('/')) throw new Error('Top-level route path must be absolute');
  if (depth > 0 && normalized.startsWith('/')) throw new Error('Child route path must be relative');

  // 只归一化一个尾斜杠；中间或额外的空段都保留并报错。
  let body = depth === 0 ? normalized.slice(1) : normalized;
  if (body.endsWith('/')) body = body.slice(0, -1);
  if (normalized === '/') return { kind: 'path', src: src.trim(), segments: [] };
  const names = new Set<string>();
  const segments: RoutePathSegment[] = body.split('/').map(segment => {
    if (!segment) throw new Error('Route path cannot contain empty segments');
    if (segment.startsWith(':')) {
      const name = segment.slice(1);
      if (!parameterName.test(name) || forbiddenNames.has(name)) throw new Error(`Invalid route parameter name: ${name}`);
      if (names.has(name)) throw new Error(`Duplicate route parameter name: ${name}`);
      names.add(name);
      return { kind: 'parameter', name };
    }
    try {
      return { kind: 'static', value: decodeURIComponent(segment) };
    } catch {
      throw new Error(`Invalid encoding in route path segment: ${segment}`);
    }
  });
  return { kind: 'path', src: src.trim(), segments };
}

/**
 * 匹配已拆分但未解码的 pathname 段，返回本条声明消费的前缀长度。
 * 每段只解码一次；编码的斜杠仍属于同一个段。index 由分组 fallback 逻辑处理。
 * 不足、空段、非法 URL 编码或静态段不符时返回 undefined，不负责同级选择。
 */
export function matchRoutePath(
  parsed: ParsedRouteDeclaration,
  pathSegments: readonly string[],
): RoutePathMatch | undefined {
  if (parsed.kind === 'index' || pathSegments.length < parsed.segments.length) return undefined;
  const params: Record<string, string> = Object.create(null);
  for (let i = 0; i < parsed.segments.length; i++) {
    const segment = parsed.segments[i];
    const input = pathSegments[i];
    if (typeof input !== 'string' || !input) return undefined;
    let value: string;
    try {
      value = decodeURIComponent(input);
    } catch {
      return undefined;
    }
    if (segment.kind === 'static') {
      if (segment.value !== value) return undefined;
    } else {
      params[segment.name] = value;
    }
  }
  return { params, consumed: parsed.segments.length };
}
