import type { ParsedTemplateFragment } from './fragment.js';
import type { HandlerSource } from './handlers.js';
import { parseTextSegments } from './binding/expression.js';
import { parseEventDeclaration } from './binding/event.js';
import type { EventDeclaration } from './binding/event.js';
import { parseForeach, parseHandlerPath, parseValuePath } from './binding/path.js';
import type { ForeachDeclaration, HandlerPath, ValuePath } from './binding/path.js';

export interface EventPlan {
  readonly declaration: EventDeclaration;
  readonly handler?: HandlerPath;
  readonly factory?: number;
}

export interface ElementPlan {
  readonly kind: 'element' | 'fragment';
  readonly node: Element;
  readonly children: readonly NodePlan[];
  readonly bindings: readonly { name: string; path: ValuePath }[];
  readonly bulk?: ValuePath;
  readonly model?: ValuePath;
  readonly html?: ValuePath;
  readonly events: readonly EventPlan[];
}

export type NodePlan =
  | { readonly kind: 'literal'; readonly node: Node }
  | { readonly kind: 'text'; readonly path: ValuePath }
  | ElementPlan
  | { readonly kind: 'foreach'; readonly declaration: ForeachDeclaration; readonly child: NodePlan }
  | { readonly kind: 'if'; readonly branches: readonly { when?: ValuePath; child: NodePlan }[] };

export interface TemplatePlan {
  readonly children: readonly NodePlan[];
  readonly handlers: readonly HandlerSource[];
}

/** 结构和路径只准备一次。动态实例复用计划，实例化时才取得业务引用及创建本地状态。 */
export function planTemplate(parsed: ParsedTemplateFragment, inheritedAliases: ReadonlySet<string> = new Set()): TemplatePlan {
  const handlers: HandlerSource[] = [];
  const structuralNames = new Set(['ns-foreach', 'ns-key', 'ns-index', 'ns-if', 'ns-else-if', 'ns-else']);

  function children(owner: Element | DocumentFragment, aliases: ReadonlySet<string>, raw = false): NodePlan[] {
    const result: NodePlan[] = [];
    const nodes = [...owner.childNodes];
    for (let index = 0; index < nodes.length; index++) {
      const node = nodes[index];
      if (node.nodeType === 3 && !raw) {
        for (const part of parseTextSegments(node.textContent ?? '')) {
          result.push(part.kind === 'text'
            ? { kind: 'literal', node: node.ownerDocument!.createTextNode(part.value) }
            : { kind: 'text', path: parseValuePath(part.path, aliases) });
        }
        continue;
      }
      if (node.nodeType !== 1) { result.push({ kind: 'literal', node }); continue; }
      const element = node as Element;
      if (element.hasAttribute('ns-else') || element.hasAttribute('ns-else-if')) throw new Error('Conditional branch requires a preceding ns-if');
      if (element.hasAttribute('ns-if') && !element.hasAttribute('ns-foreach')) {
        const branches: { when?: ValuePath; child: NodePlan }[] = [{
          when: parseValuePath(element.getAttribute('ns-if')!, aliases), child: elementPlan(element, aliases),
        }];
        const gaps: Node[] = [];
        while (index + 1 < nodes.length) {
          let next = index + 1;
          while (next < nodes.length && (nodes[next].nodeType === 8 || nodes[next].nodeType === 3 && !nodes[next].textContent?.trim())) next++;
          const candidate = nodes[next];
          if (!candidate || candidate.nodeType !== 1) break;
          const branch = candidate as Element;
          if (!branch.hasAttribute('ns-else-if') && !branch.hasAttribute('ns-else')) break;
          if (branch.hasAttribute('ns-if') || branch.hasAttribute('ns-foreach')
            || branch.hasAttribute('ns-else-if') && branch.hasAttribute('ns-else')) throw new Error('Conflicting conditional branch declarations');
          if (branch.hasAttribute('ns-else') && branch.getAttribute('ns-else')!.trim()) throw new Error('ns-else does not accept a value');
          gaps.push(...nodes.slice(index + 1, next));
          branches.push({
            ...(branch.hasAttribute('ns-else-if') ? { when: parseValuePath(branch.getAttribute('ns-else-if')!, aliases) } : {}),
            child: elementPlan(branch, aliases),
          });
          index = next;
          if (branch.hasAttribute('ns-else')) break;
        }
        result.push({ kind: 'if', branches }, ...gaps.map(node => ({ kind: 'literal' as const, node })));
      } else result.push(compile(element, aliases));
    }
    return result;
  }

  function compile(element: Element, aliases: ReadonlySet<string>): NodePlan {
    const loop = element.getAttribute('ns-foreach');
    if (loop !== null) {
      const declaration = parseForeach(loop, element.getAttribute('ns-key'), element.getAttribute('ns-index'), aliases);
      const row = new Set(aliases);
      row.add(declaration.alias);
      if (declaration.index) row.add(declaration.index);
      const child = elementPlan(element, row);
      return {
        kind: 'foreach', declaration,
        child: element.hasAttribute('ns-if') ? { kind: 'if', branches: [{ when: parseValuePath(element.getAttribute('ns-if')!, row), child }] } : child,
      };
    }
    return elementPlan(element, aliases);
  }

  function elementPlan(element: Element, aliases: ReadonlySet<string>): NodePlan {
    const isTemplate = element.localName === 'template';
    if (isTemplate && !['ns-foreach', 'ns-if', 'ns-else-if', 'ns-else'].some(name => element.hasAttribute(name))) {
      return { kind: 'literal', node: element };
    }
    if (!element.hasAttribute('ns-foreach') && (element.hasAttribute('ns-key') || element.hasAttribute('ns-index'))) {
      throw new Error('ns-key and ns-index require ns-foreach on the same element');
    }
    const owner = isTemplate ? (element as HTMLTemplateElement).content : element;
    const events: EventPlan[] = [];
    const bindings: { name: string; path: ValuePath }[] = [];
    let bulk: ValuePath | undefined;
    let model: ElementPlan['model'];
    let html: ValuePath | undefined;
    for (const attribute of element.attributes) {
      const { name, value } = attribute;
      if (structuralNames.has(name)) continue;
      if (name === 'ns-bind') bulk = parseValuePath(value, aliases);
      else if (name.startsWith('ns-bind-')) {
        const target = name.slice(8);
        if (!target || target.includes('.')) throw new Error(`Invalid ns-bind target: ${target}`);
        bindings.push({ name: target, path: parseValuePath(value, aliases) });
      } else if (name === 'ns-model') {
        const path = parseValuePath(value, aliases);
        if (!path.path.length || path.root === 'properties' || path.root === 'attributes') throw new Error('Model requires a writable state or row field');
        model = path;
      }
      else if (name === 'ns-html') html = parseValuePath(value, aliases);
      else if (name.startsWith('ns-on-')) {
        const declaration = parseEventDeclaration(name);
        const handler = parseHandlerPath(value);
        if (handler) events.push({ declaration, handler });
        else {
          const factory = handlers.length;
          handlers.push({ expression: value, aliases: [...aliases] });
          events.push({ declaration, factory });
        }
      } else if (name.startsWith('ns-')) throw new Error(`Unknown template directive: ${name}`);
    }
    if (isTemplate && (bindings.length || bulk || model || html || events.length)) {
      throw new Error('A structural template has no element target for value, model or event bindings');
    }
    if (html && model) throw new Error('ns-html and ns-model cannot own the same element');
    const raw = ['script', 'style', 'textarea', 'noscript'].includes(element.localName);
    if (html) {
      for (const node of [owner, ...owner.querySelectorAll('*')]) {
        if (node !== owner && [...(node as Element).attributes].some(attribute => attribute.name.startsWith('ns-'))) {
          throw new Error('ns-html cannot own a subtree containing template bindings');
        }
        for (const child of node.childNodes) {
          if (child.nodeType === 3 && parseTextSegments(child.textContent ?? '').some(part => part.kind === 'binding')) {
            throw new Error('ns-html cannot share its content with text interpolation');
          }
        }
      }
    }
    const nested = html ? [] : children(owner, aliases, raw);
    return {
      kind: isTemplate ? 'fragment' : 'element', node: element,
      children: nested,
      bindings, bulk, model, html, events,
    };
  }

  try { return { children: children(parsed.content, inheritedAliases), handlers }; }
  catch (cause) { throw new Error(`Invalid template bindings in ${parsed.sourceURL}: ${cause instanceof Error ? cause.message : String(cause)}`, { cause }); }
}
