import { createScope } from '../lifecycle/scope.js';
import { emptyInputs } from '../component/fields.js';
import type { Behavior, BehaviorContext, BehaviorEnvironment, BehaviorInstance, BehaviorLease, BehaviorResult } from './types.js';

function validateResult(value: unknown): asserts value is BehaviorResult {
  if (value !== null && (typeof value === 'object' || typeof value === 'function')
    && 'then' in value && typeof value.then === 'function') {
    // 初始化不接受 Promise；观察其拒绝，避免失败回收后产生未处理拒绝。
    void Promise.resolve(value).catch(() => {});
    throw new TypeError('Behavior must synchronously return { state, actions }');
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError('Behavior must synchronously return { state, actions }');
  }
  const { state, actions } = value as BehaviorResult;
  if (!state || typeof state !== 'object') {
    throw new TypeError('Behavior state must be an object');
  }
  if (!actions || typeof actions !== 'object' || Array.isArray(actions)
    || Object.values(actions).some(action => typeof action !== 'function')) {
    throw new TypeError('Behavior actions must be an object of functions');
  }
}

/** 调用普通行为函数并拥有它登记的资源；每次调用都创建独立作用域。 */
export function createBehaviorInstance<Result extends BehaviorResult>(
  behavior: Behavior<Result>,
  environment: BehaviorEnvironment = {},
): BehaviorInstance<Result> {
  if (typeof behavior !== 'function') throw new TypeError('Behavior must be a function');
  const scope = createScope();
  const dependencies = createScope();
  const leases = new Map<string, BehaviorLease>();
  let disposed = false;
  let initializing = true;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    const errors: unknown[] = [];
    try { scope.dispose(); } catch (error) { errors.push(error); }
    // 自身清理可能读取已有依赖；业务依赖始终比自身资源活得更久。
    try { dependencies.dispose(); } catch (error) { errors.push(error); }
    leases.clear();
    if (errors.length === 1) throw errors[0];
    if (errors.length > 1) throw new AggregateError(errors, 'Behavior resources and dependencies cleanup failed');
  };
  const context: BehaviorContext = Object.freeze({
    properties: environment.properties ?? emptyInputs,
    attributes: environment.attributes ?? emptyInputs,
    route: environment.route,
    onMount(callback: (host: HTMLElement) => void) {
      if (typeof callback !== 'function') throw new TypeError('onMount callback must be a function');
      if (!initializing || disposed) throw new Error('onMount must be registered during Behavior initialization');
      if (!environment.onMount) throw new Error('onMount requires a component Behavior');
      environment.onMount(callback);
    },
    getBehavior<Value extends BehaviorResult = BehaviorResult>(name: string): Value {
      if (disposed) throw new Error('Behavior instance has been disposed');
      let lease = leases.get(name);
      if (!lease) {
        if (!environment.acquireBehavior) throw new Error(`Business Behavior resolver is unavailable: ${name}`);
        lease = environment.acquireBehavior(name);
        // 取得依赖也可能同步触发拥有者退出，不能留下退出后的引用。
        if (disposed) {
          lease.release();
          throw new Error('Behavior instance has been disposed');
        }
        leases.set(name, lease);
        dependencies.add(lease.release);
      }
      return lease.value as Value;
    },
    onDispose: scope.add,
    subscribe<T>(source: { subscribe(listener: (value: T) => void): () => void }, listener: (value: T) => void) {
      if (disposed) throw new Error('Behavior instance has been disposed');
      // subscribe 中的同步回调可能触发销毁；add 随后会立即停止刚建立的订阅。
      return scope.add(source.subscribe(listener));
    },
  });

  try {
    let value: unknown;
    try { value = Reflect.apply(behavior, undefined, [context]); }
    finally { initializing = false; }
    validateResult(value);
    return Object.freeze({
      value: value as Result,
      get disposed() { return disposed; },
      dispose,
    });
  } catch (error) {
    try { dispose(); }
    catch (cleanupError) {
      throw new AggregateError([error, cleanupError], 'Behavior initialization and cleanup failed');
    }
    throw error;
  }
}
