import { createBehaviorInstance } from '../behavior/instance.js';
import { loadInlineBehavior } from '../behavior/module.js';
import type { Behavior, BehaviorInstance, BehaviorLease, BehaviorResult, RouteContext } from '../behavior/types.js';
import { createScope } from '../lifecycle/scope.js';
import type { Scope } from '../lifecycle/scope.js';
import { Signal, batch } from '../state/signal.js';
import type { Readable } from '../state/signal.js';
import { bindHandler } from './binding/event.js';
import { createElementBindings } from './binding/attribute.js';
import { bindModelTarget } from './binding/control.js';
import { readOwnPath, writeOwnPath } from './binding/path.js';
import type { ValuePath } from './binding/path.js';
import { createErrorReporter } from './errors.js';
import type { InlineBehaviorDeclaration, ParsedTemplateFragment } from './fragment.js';
import { loadHandlerFactory } from './handlers.js';
import type { HandlerFactory } from './handlers.js';
import { planTemplate } from './plan.js';
import type { ElementPlan, NodePlan, TemplatePlan } from './plan.js';
import { emptyInputs, readComponentFields } from '../component/fields.js';
import type { ComponentFields, InputReferences } from '../component/fields.js';

export interface TemplateBindingsContext {
  readonly variables?: ReadonlyMap<string, Readable<unknown>>;
  readonly properties?: InputReferences;
  readonly attributes?: InputReferences;
}

export interface TemplateViewContext extends TemplateBindingsContext {
  readonly local?: BehaviorResult;
  readonly acquireBehavior?: (name: string) => BehaviorLease;
  readonly route?: RouteContext;
}

export interface ChildViewResources {
  stopBindings(): void;
  dispose(): void;
}

export interface TemplateViewOptions {
  readonly signal?: AbortSignal;
  readonly onError: (error: unknown) => void;
  readonly onElement?: (element: Element, local: BehaviorResult | undefined, context: TemplateBindingsContext) => ChildViewResources | void;
}

export interface PreparedTemplateView extends ChildViewResources {
  readonly content: DocumentFragment;
  /** 组件 Behavior 返回的动作；宿主控制器将其发布为组件公开动作。 */
  readonly actions: BehaviorResult['actions'] | undefined;
  mount(root: ShadowRoot): void;
}

/** 只读定义可被多个实例复用；不持有实例 DOM、状态或资源作用域。 */
export interface PreparedTemplateDefinition {
  readonly sourceURL: string;
  readonly plan: TemplatePlan;
  readonly behavior?: InlineBehaviorDeclaration;
  readonly factory?: Behavior;
  readonly handlerFactory: HandlerFactory;
  readonly fields: ComponentFields;
}

/** 内部模板区域持有绑定、业务引用和子组件；组件 Behavior 由整个视图独立持有。 */
interface Region {
  readonly owner: Node;
  readonly bindings: Scope;
  readonly children: Set<Region>;
  readonly business: Map<string, BehaviorLease>;
  readonly variables: ReadonlyMap<string, Readable<unknown>>;
  parent?: Region;
  childResources?: ChildViewResources;
  mounted?: () => void;
  end?: Node;
  failureScope?: MountScope;
  didMount: boolean;
  bindingsStopped: boolean;
  disposed: boolean;
}

/** 一次模板节点或结构展开的 DOM 范围，不表示组件实例或 Behavior 实例。 */
interface Instance {
  readonly first: Node;
  readonly last: Node;
  readonly region?: Region;
}

/** 一次结构创建的最外层分支／行；仅在原生控件初次接入完成前持有。 */
interface MountScope {
  remove(): void;
}

function throwErrors(errors: unknown[], message: string): void {
  if (errors.length === 1) throw errors[0];
  if (errors.length > 1) throw new AggregateError(errors, message);
}

function awaitWithSignal<T>(promise: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return promise;
  return new Promise((resolve, reject) => {
    const abort = () => { signal.removeEventListener('abort', abort); reject(signal.reason); };
    signal.addEventListener('abort', abort, { once: true });
    promise.then(value => {
      signal.removeEventListener('abort', abort);
      if (signal.aborted) reject(signal.reason);
      else resolve(value);
    }, error => {
      signal.removeEventListener('abort', abort);
      reject(signal.aborted ? signal.reason : error);
    });
    if (signal.aborted) abort();
  });
}

export async function prepareTemplateDefinition(
  parsed: ParsedTemplateFragment,
  aliases: ReadonlySet<string> = new Set(),
  signal?: AbortSignal,
): Promise<PreparedTemplateDefinition> {
  signal?.throwIfAborted();
  const plan = planTemplate(parsed, aliases);
  const behavior = parsed.behavior;
  const [factory, handlerFactory] = await awaitWithSignal(Promise.all([
    behavior ? loadInlineBehavior(behavior.source, behavior.sourceURL) : undefined,
    loadHandlerFactory(plan.handlers, parsed.sourceURL),
  ]), signal);
  return Object.freeze({
    sourceURL: parsed.sourceURL, plan, behavior, factory, fields: readComponentFields(factory), handlerFactory,
  });
}

/** 每次实例化都创建新的根片段；并发消费者绝不共享可变 DocumentFragment。 */
export function instantiateTemplate(
  definition: PreparedTemplateDefinition,
  context: TemplateViewContext,
  options: TemplateViewOptions,
): PreparedTemplateView {
  const content = document.createDocumentFragment();
  const { factory, handlerFactory } = definition;
  let behaviorInstance: BehaviorInstance | undefined;
  let localValue = context.local;
  const mountCallbacks: ((host: HTMLElement) => void)[] = [];
  const report = createErrorReporter(options.onError);
  const signal = options.signal;
  const regions = new Map<Node, Region>();
  let rootRegion: Region | undefined;
  let mountedRoot: ShadowRoot | undefined;
  let observer: MutationObserver | undefined;
  let disposed = false;
  let bindingsStopped = false;
  let abortListener: (() => void) | undefined;
  const pendingMounts = new Set<Region>();
  let constructionScope: MountScope | undefined;
  let constructionDepth = 0;
  let dispatchingMounts = false;
  let initialMounted = false;
  const properties = context.properties ?? emptyInputs;
  const attributes = context.attributes ?? emptyInputs;
  const values = (references: InputReferences): object => Object.freeze(Object.defineProperties(Object.create(null),
    Object.fromEntries(Object.entries(references).map(([name, reference]) => [name, { enumerable: true, get: () => reference.get() }]))));
  const propertyValues = values(properties);
  const attributeValues = values(attributes);

  function addRegion(owner: Node, parent?: Region, variables?: ReadonlyMap<string, Readable<unknown>>): Region {
    if (disposed || bindingsStopped) throw new Error('Cannot initialize a stopped template region');
    const region: Region = {
      owner, parent,
      variables: variables ?? parent?.variables ?? context.variables ?? new Map(),
      bindings: createScope(), children: new Set(), business: new Map(), bindingsStopped: false, disposed: false,
      didMount: false, failureScope: constructionScope,
    };
    parent?.children.add(region);
    regions.set(owner, region);
    return region;
  }

  function collectSubtrees(regionRoots: Iterable<Region>): Region[] {
    const selected = new Set<Region>();
    const visit = (region: Region) => {
      if (region.disposed || selected.has(region)) return;
      selected.add(region);
      for (const child of region.children) visit(child);
    };
    for (const region of regionRoots) visit(region);
    return [...regions.values()].filter(region => selected.has(region));
  }

  function stopRegions(list: readonly Region[], errors: unknown[]): void {
    const stopping = list.filter(region => !region.bindingsStopped);
    for (const region of stopping) {
      region.bindingsStopped = true;
      if (region === rootRegion) mountCallbacks.length = 0;
      pendingMounts.delete(region);
    }
    for (const region of stopping) {
      try { region.bindings.dispose(); } catch (error) { errors.push(error); }
    }
    for (const region of stopping) {
      try { region.childResources?.stopBindings(); } catch (error) { errors.push(error); }
    }
  }

  function disposeRegions(list: readonly Region[]): void {
    const active = list.filter(region => !region.disposed);
    const errors: unknown[] = [];
    for (const region of active) region.disposed = true;
    stopRegions(active, errors);
    for (const region of [...active].reverse()) {
      try { region.childResources?.dispose(); } catch (error) { errors.push(error); }
      if (region === rootRegion) {
        try { behaviorInstance?.dispose(); } catch (error) { errors.push(error); }
        behaviorInstance = undefined;
        localValue = undefined;
      }
      for (const lease of [...region.business.values()].reverse()) {
        try { lease.release(); } catch (error) { errors.push(error); }
      }
      region.business.clear();
      region.parent?.children.delete(region);
      regions.delete(region.owner);
      region.children.clear();
      region.parent = undefined;
      region.childResources = undefined;
      region.mounted = undefined;
      region.failureScope = undefined;
    }
    throwErrors(errors, 'Template region cleanup failed');
  }

  function stopBindings(): void {
    if (bindingsStopped) return;
    bindingsStopped = true;
    const errors: unknown[] = [];
    stopRegions([...regions.values()], errors);
    throwErrors(errors, 'Template binding cleanup failed');
  }

  function dispose(): void {
    if (disposed) return;
    disposed = true;
    observer?.disconnect();
    observer = undefined;
    if (abortListener) signal?.removeEventListener('abort', abortListener);
    abortListener = undefined;
    bindingsStopped = true;
    try { disposeRegions([...regions.values()]); }
    finally { rootRegion = undefined; mountedRoot = undefined; }
  }

  function cleanRemovedNodes(mutations: readonly MutationRecord[]): void {
    if (disposed || !mountedRoot) return;
    const detached = new Set<Region>();
    const check = (node: Node) => {
      const region = regions.get(node);
      if (region && !mountedRoot!.contains(node)) detached.add(region);
    };
    for (const mutation of mutations) {
      for (const node of mutation.removedNodes) {
        check(node);
        const walker = node.ownerDocument!.createTreeWalker(node, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT | NodeFilter.SHOW_COMMENT);
        while (walker.nextNode()) check(walker.currentNode);
      }
    }
    if (detached.size) {
      try { disposeRegions(collectSubtrees(detached)); } catch (error) { report(error); }
    }
  }

  const view: PreparedTemplateView = Object.freeze({
    content, stopBindings, dispose,
    get actions() { return behaviorInstance?.value.actions; },
    mount(root: ShadowRoot) {
      if (disposed || bindingsStopped) throw new Error('Cannot mount a stopped Template view');
      if (mountedRoot) throw new Error('Template view is already mounted');
      try {
        signal?.throwIfAborted();
        if (!root || root.nodeType !== 11 || !('host' in root)) throw new TypeError('Template view root must be a ShadowRoot');
        mountedRoot = root;
        observer = new MutationObserver(cleanRemovedNodes);
        observer.observe(root, { childList: true, subtree: true });
        root.append(content);
        inserted(rootRegion ? [rootRegion] : []);
        // 组件只挂载一次；普通结构更新只执行原生绑定，不再创建区域 Behavior。
        for (const callback of mountCallbacks.splice(0)) {
          if (disposed || bindingsStopped) break;
          try {
            const result: unknown = Reflect.apply(callback, undefined, [root.host]);
            if (result !== null && (typeof result === 'object' || typeof result === 'function') && typeof (result as PromiseLike<unknown>).then === 'function') {
              void Promise.resolve(result).catch(cause => report(new Error(`Late onMount rejection at ${definition.behavior?.sourceURL}`, { cause })));
              throw new TypeError('onMount callback must be synchronous; use onDispose for cleanup');
            }
          } catch (cause) {
            throw new Error(`Behavior onMount failed at ${definition.behavior?.sourceURL}`, { cause });
          }
        }
        initialMounted = true;
        signal?.throwIfAborted();
      } catch (error) {
        try { dispose(); }
        catch (cleanupError) { throw new AggregateError([error, cleanupError], 'Template mount and cleanup failed'); }
        throw error;
      }
    },
  });

  function business(name: string, region: Region): BehaviorResult {
    if (region.disposed || region.bindingsStopped) throw new Error('Template region has been disposed');
    let lease = region.business.get(name);
    if (!lease) {
      if (!context.acquireBehavior) throw new Error(`Business Behavior registry is required for ${name} in ${definition.sourceURL}`);
      lease = context.acquireBehavior(name);
      if (region.disposed || region.bindingsStopped) { lease.release(); throw new Error('Template region has been disposed'); }
      region.business.set(name, lease);
    }
    signal?.throwIfAborted();
    return lease.value;
  }

  function local(): BehaviorResult {
    if (!localValue) throw new Error(`Local Behavior is required for this binding in ${definition.sourceURL}`);
    return localValue;
  }

  function rootReader(path: ValuePath, region: Region): () => unknown {
    if (path.root === 'local') { const value = local(); return () => value.state; }
    if (path.root === 'business') { const value = business(path.name!, region); return () => value.state; }
    if (path.root === 'properties' || path.root === 'attributes') {
      const references = path.root === 'properties' ? properties : attributes;
      if (path.path.length && !Object.hasOwn(references, path.path[0])) {
        throw new Error(`Unknown component input ${path.root}.${path.path[0]} in ${definition.sourceURL}`);
      }
      const inputValues = path.root === 'properties' ? propertyValues : attributeValues;
      return () => inputValues;
    }
    const variable = region.variables.get(path.name!);
    if (!variable) throw new Error(`Unknown template alias: ${path.name}`);
    return () => variable.get();
  }

  function reader(path: ValuePath, region: Region): () => unknown {
    // 取得具名实例发生在纯 Computed 之外。
    const readRoot = rootReader(path, region);
    return () => readOwnPath(readRoot(), path.path);
  }

  function range(parent: Node, owner: Region, label: string, variables?: ReadonlyMap<string, Readable<unknown>>): Instance & { region: Region } {
    const first = document.createComment(label);
    const last = document.createComment(`/${label}`);
    parent.appendChild(first);
    parent.appendChild(last);
    const region = addRegion(first, owner, variables);
    region.end = last;
    return { first, last, region };
  }

  function removeDOM(instance: Instance): void {
    let node: Node | null = instance.first;
    while (node) {
      const next: Node | null = node === instance.last ? null : node.nextSibling;
      node.parentNode?.removeChild(node);
      node = next;
    }
  }

  function destroy(instance: Instance): void {
    try { if (instance.region) disposeRegions(collectSubtrees([instance.region])); }
    finally { removeDOM(instance); }
  }

  function construct<T>(scope: MountScope, run: () => T): T {
    const previous = constructionScope;
    constructionScope ??= scope;
    constructionDepth++;
    try { return run(); }
    finally { constructionDepth--; constructionScope = previous; }
  }

  /** 仅接入已经进入原组件 ShadowRoot 的新区域原生控件；临时片段中的内层构造由外层插入统一接入。 */
  function inserted(regionRoots: readonly Region[]): void {
    if (!mountedRoot || disposed || bindingsStopped) return;
    for (const region of collectSubtrees(regionRoots)) {
      if (!region.didMount && (region === rootRegion || mountedRoot.contains(region.owner))) pendingMounts.add(region);
    }
    if (constructionDepth || dispatchingMounts) return;
    dispatchingMounts = true;
    const failures: unknown[] = [];
    const valid = (region: Region): boolean => {
      if (disposed || bindingsStopped || region.disposed || region.bindingsStopped) return false;
      let detached: Region | undefined;
      for (let owner: Region | undefined = region; owner; owner = owner.parent) {
        if (owner.disposed || owner.bindingsStopped) return false;
        if (owner !== rootRegion && (!mountedRoot!.contains(owner.owner) || owner.end && !mountedRoot!.contains(owner.end))) detached = owner;
      }
      if (!detached) return true;
      try { disposeRegions(collectSubtrees([detached])); } catch (error) { failures.push(error); }
      return false;
    };
    const fail = (region: Region, cause: unknown, phase: string) => {
      const error = new Error(`${phase} failed at ${definition.sourceURL} (${region.owner.nodeName})`, { cause });
      if (!initialMounted) throw error;
      failures.push(error);
      try {
        if (region.failureScope) region.failureScope.remove();
        else disposeRegions(collectSubtrees([region]));
      } catch (cleanup) { failures.push(cleanup); }
    };
    try {
      while (pendingMounts.size) {
        const batch = new Set(pendingMounts);
        pendingMounts.clear();
        for (const region of batch) {
          if (!valid(region)) continue;
          region.didMount = true;
          try { region.mounted?.(); } catch (error) { fail(region, error, 'Native control mount'); }
        }
        for (const region of batch) region.failureScope = undefined;
      }
    } finally { dispatchingMounts = false; }
    throwErrors(failures, 'Native control mount and cleanup failed');
  }

  function moveBefore(instance: Instance, parent: Node, before: Node): void {
    if (instance.last.nextSibling === before && instance.first.parentNode === parent) return;
    const nodes: Node[] = [];
    let node: Node | null = instance.first;
    while (node) {
      nodes.push(node);
      if (node === instance.last) break;
      node = node.nextSibling;
    }
    const movable = parent as Node & { moveBefore?: (node: Node, before: Node) => void };
    for (const node of nodes) {
      if (movable.moveBefore && node.isConnected && parent.isConnected) movable.moveBefore(node, before);
      else parent.insertBefore(node, before);
    }
  }

  function render(plan: NodePlan, parent: Node, owner: Region): Instance {
    signal?.throwIfAborted();
    if (plan.kind === 'literal') {
      const node = plan.node.cloneNode(true);
      parent.appendChild(node);
      return { first: node, last: node };
    }
    if (plan.kind === 'text') {
      const node = document.createTextNode('');
      parent.appendChild(node);
      const region = addRegion(node, owner);
      const read = reader(plan.path, region);
      region.bindings.add(new Signal.Computed(() => { const value = read(); return value == null ? '' : String(value); }).subscribe(value => {
        if (node.data !== value) node.data = value;
      }));
      return { first: node, last: node, region };
    }
    if (plan.kind === 'if') {
      const instance = range(parent, owner, 'ns-if');
      const reads = plan.branches.map(branch => branch.when ? reader(branch.when, instance.region) : () => true);
      let current: Instance | undefined;
      instance.region.bindings.add(new Signal.Computed(() => reads.findIndex(read => !!read())).subscribe(index => {
        const failures: unknown[] = [];
        if (current) {
          try { destroy(current); } catch (error) { failures.push(error); }
          current = undefined;
        }
        if (index < 0) { throwErrors(failures, 'Conditional cleanup failed'); return; }
        const staging = document.createDocumentFragment();
        const branch = range(staging, instance.region, 'ns-branch');
        const scope: MountScope = { remove() { if (current === branch) current = undefined; destroy(branch); } };
        branch.region.failureScope = constructionScope ?? scope;
        try {
          construct(scope, () => {
            const content = document.createDocumentFragment();
            render(plan.branches[index].child, content, branch.region);
            staging.insertBefore(content, branch.last);
            instance.last.parentNode!.insertBefore(staging, instance.last);
          });
          current = branch;
        } catch (error) {
          failures.push(error);
          try { destroy(branch); } catch (cleanup) { failures.push(cleanup); }
          if (current === branch) current = undefined;
        }
        if (current === branch) {
          try { inserted([branch.region]); } catch (error) { failures.push(error); }
        }
        throwErrors(failures, 'Conditional initialization and cleanup failed');
      }));
      return instance;
    }
    if (plan.kind === 'foreach') {
      const instance = range(parent, owner, 'ns-foreach');
      const { declaration } = plan;
      const read = reader(declaration.source, instance.region);
      type Row = { instance: Instance & { region: Region }; item: InstanceType<typeof Signal.State<unknown>>; index?: InstanceType<typeof Signal.State<number>> };
      let rows = new Map<string | number, Row>();
      const entries = new Signal.Computed(() => {
        const items = read();
        if (!Array.isArray(items)) throw new TypeError('ns-foreach requires an array');
        const keys = new Set<string | number>();
        return Array.from(items, (item: unknown, index) => {
          const key = readOwnPath(item, declaration.key.path);
          if (typeof key !== 'string' && (typeof key !== 'number' || !Number.isFinite(key))) throw new TypeError('ns-key requires a string or finite number');
          if (keys.has(key)) throw new Error(`Duplicate ns-key: ${key}`);
          keys.add(key);
          return { key, item, index };
        });
      });
      instance.region.bindings.add(entries.subscribe(values => {
        const next = new Map<string | number, Row>();
        const created: Row[] = [];
        try {
          for (const value of values) {
            let row = rows.get(value.key);
            if (!row || row.instance.region.disposed) {
              const variables = new Map(instance.region.variables);
              const item = new Signal.State(value.item);
              const index = declaration.index ? new Signal.State(value.index) : undefined;
              variables.set(declaration.alias, item);
              if (declaration.index) variables.set(declaration.index, index!);
              const staging = document.createDocumentFragment();
              const rowInstance = range(staging, instance.region, 'ns-row', variables);
              row = { instance: rowInstance, item, index };
              created.push(row);
              const createdRow = row;
              const scope: MountScope = { remove() {
                if (rows.get(value.key) === createdRow) rows.delete(value.key);
                destroy(rowInstance);
              } };
              rowInstance.region.failureScope = constructionScope ?? scope;
              construct(scope, () => {
                const content = document.createDocumentFragment();
                render(plan.child, content, rowInstance.region);
                staging.insertBefore(content, rowInstance.last);
              });
            }
            next.set(value.key, row);
          }
        } catch (error) {
          const errors = [error];
          for (const row of created) { try { destroy(row.instance); } catch (cleanup) { errors.push(cleanup); } }
          throwErrors(errors, 'List initialization and cleanup failed');
          return;
        }
        const failures: unknown[] = [];
        for (const [key, row] of rows) if (!next.has(key)) {
          try { destroy(row.instance); } catch (error) { failures.push(error); }
        }
        rows = next;
        batch(() => {
          for (const value of values) {
            const row = rows.get(value.key)!;
            row.item.set(value.item);
            row.index?.set(value.index);
          }
        });
        let before = instance.last;
        for (const row of [...rows.values()].reverse()) {
          moveBefore(row.instance, instance.last.parentNode!, before);
          before = row.instance.first;
        }
        try { inserted(created.map(row => row.instance.region)); } catch (error) { failures.push(error); }
        throwErrors(failures, 'List row cleanup failed');
      }));
      instance.region.bindings.add(() => rows.clear());
      return instance;
    }
    return renderElement(plan, parent, owner);
  }

  function renderElement(plan: ElementPlan, parent: Node, owner: Region): Instance {
    const fragment = plan.kind === 'fragment';
    const element = fragment ? undefined : plan.node.cloneNode(false) as Element;
    const instance = fragment ? range(parent, owner, 'ns-fragment') : (() => {
      parent.appendChild(element!);
      return { first: element!, last: element!, region: addRegion(element!, owner) };
    })();
    const region = instance.region;
    const environment = Object.freeze({
      behaviors: new Proxy(Object.create(null) as Record<string, BehaviorResult>, {
        get(_target, name) { return typeof name === 'string' ? business(name, region) : undefined; },
        set() { throw new TypeError('context.behaviors is readonly'); },
      }),
    });
    const handlers = plan.events.map(event => {
      if (event.handler) {
        const value = event.handler.behavior === undefined ? local() : business(event.handler.behavior, region);
        const handler = Object.hasOwn(value.actions, event.handler.name) ? value.actions[event.handler.name] : undefined;
        if (typeof handler !== 'function') throw new Error(`Unknown action: ${event.handler.name}`);
        return handler as (event: Event) => unknown;
      }
      const frame = handlerFactory(event.factory!, {
        state: localValue?.state, actions: localValue?.actions, context: environment,
        properties: propertyValues, attributes: attributeValues,
        readAlias: name => region.variables.get(name)!.get(),
      });
      if (region.variables.size) {
        region.bindings.add(new Signal.Computed(() => [...region.variables.values()].map(value => value.get())).subscribe(frame.update));
      }
      return (event: Event) => { frame.update(); return Reflect.apply(frame.handler, undefined, [event]); };
    });

    // 子 option 及其文本先就绪，父 select 再应用当前模型。
    const content = fragment ? document.createDocumentFragment() : element!;
    for (const child of plan.children) render(child, content, region);
    if (fragment) { parent.insertBefore(content, instance.last); return instance; }
    const bindings = createElementBindings(element!, definition.sourceURL, region.bindings, report);
    const configuration = (name: string) => ['type', 'multiple', 'defaultvalue', 'defaultchecked', 'defaultselected'].includes(name) ? 0 : 1;
    for (const binding of [...plan.bindings].sort((a, b) => configuration(a.name) - configuration(b.name))) {
      bindings.bind(binding.name, reader(binding.path, region));
    }
    if (plan.bulk) bindings.bindMany(reader(plan.bulk, region));
    if (plan.html) {
      const read = reader(plan.html, region);
      region.bindings.add(new Signal.Computed(read).subscribe(value => {
        if (value != null && typeof value !== 'string' && Object.prototype.toString.call(value) !== '[object TrustedHTML]') {
          throw new TypeError('ns-html requires an HTML string or TrustedHTML');
        }
        // 保留 TrustedHTML 的原始对象供浏览器执行 Trusted Types 检查。
        element!.innerHTML = (value ?? '') as string;
      }));
    }
    if (plan.model) {
      const readRoot = rootReader(plan.model, region);
      const model = bindModelTarget(element!, {
        read: () => readOwnPath(readRoot(), plan.model!.path),
        write: value => writeOwnPath(readRoot(), plan.model!.path, value),
      }, region.bindings, report, name => bindings.claim(name, 'ns-model'));
      region.mounted = model.mount;
    }
    for (const [index, event] of plan.events.entries()) {
      bindHandler(element!, event.declaration, handlers[index], region.bindings, report);
    }
    const childResources = options.onElement?.(element!, localValue, { variables: region.variables, properties, attributes });
    if (childResources) region.childResources = childResources;
    signal?.throwIfAborted();
    return instance;
  }

  try {
    signal?.throwIfAborted();
    rootRegion = addRegion(content);
    if (factory) {
      behaviorInstance = createBehaviorInstance(factory, {
        acquireBehavior: context.acquireBehavior, route: context.route, properties, attributes,
        onMount: callback => { mountCallbacks.push(callback); },
      });
      localValue = behaviorInstance.value;
      signal?.throwIfAborted();
    }
    for (const child of definition.plan.children) render(child, content, rootRegion);
    abortListener = () => { try { dispose(); } catch (error) { report(error); } };
    signal?.addEventListener('abort', abortListener, { once: true });
    signal?.throwIfAborted();
    return view;
  } catch (error) {
    try { dispose(); }
    catch (cleanupError) { throw new AggregateError([error, cleanupError], 'Template initialization and cleanup failed'); }
    throw error;
  }
}

/** Low-level view helper; component hosts use shared definitions and isolated contexts. */
export async function prepareTemplateView(
  parsed: ParsedTemplateFragment,
  context: TemplateViewContext,
  options: TemplateViewOptions,
): Promise<PreparedTemplateView> {
  const definition = await prepareTemplateDefinition(parsed, new Set(context.variables?.keys()), options.signal);
  return instantiateTemplate(definition, context, options);
}
