import { batch, createState } from '../state/index.js';
import type { RouteContext } from '../behavior/types.js';
import type { ContentContext, ManagedResource } from '../runtime/context.js';
import { matchRoutePath, parseRouteDeclaration } from './path.js';
import type { ParsedRouteDeclaration, RoutePathMatch } from './path.js';

export interface RouteCandidate {
  readonly element: Element;
  readonly context: ContentContext;
  readonly activate: (context: ContentContext) => void;
  readonly content: ManagedResource;
}
interface RecordEntry extends RouteCandidate { parsed: ParsedRouteDeclaration }
interface Selection { entry: RecordEntry; match: RoutePathMatch; identity: string }

/** 每个逻辑父路由拥有一组；普通 include 沿用本组，并为异步候选收集登记占用。 */
export class RouteGroup implements ManagedResource {
  private entries = new Set<RecordEntry>();
  private holds = new Map<object, 'pending' | 'failed'>();
  private selected?: { entry: RecordEntry; identity: string; state: RouteContext; child: RouteGroup };
  private disposed = false;
  private queued = false;
  constructor(
    readonly depth: number,
    private offset: number,
    private parentParams: Readonly<Record<string, string>>,
    private location: () => URL,
    private report: (error: unknown) => void,
  ) {}

  hold(): { settle(): void; fail(): void; release(): void } {
    if (this.disposed) throw new Error('Route group has been disposed');
    const key = {};
    this.holds.set(key, 'pending');
    let released = false;
    return {
      settle: () => {
        if (released || this.disposed) return;
        this.holds.delete(key); released = true; this.schedule();
      },
      fail: () => {
        if (released || this.disposed) return;
        this.holds.set(key, 'failed'); this.schedule();
      },
      release: () => { released = true; this.holds.delete(key); this.schedule(); },
    };
  }

  register(candidate: RouteCandidate): ManagedResource {
    if (this.disposed) throw new Error('Route group has been disposed');
    const element = candidate.element;
    const parsed = parseRouteDeclaration({
      path: element.hasAttribute('path') ? element.getAttribute('path')! : undefined,
      index: element.hasAttribute('index'), src: element.getAttribute('src') ?? '',
    }, this.depth);
    const entry = { ...candidate, parsed };
    this.entries.add(entry);
    this.schedule();
    return {
      stopBindings: () => entry.content.stopBindings(),
      dispose: () => {
        if (!this.entries.delete(entry)) return;
        try { if (this.selected?.entry === entry) this.clear(); }
        finally { this.schedule(); }
      },
    };
  }

  schedule(): void {
    if (this.queued || this.disposed) return;
    this.queued = true;
    queueMicrotask(() => {
      this.queued = false;
      if (this.disposed) return;
      try { this.reconcile(); } catch (error) { this.report(error); }
    });
  }

  private choose(url: URL): Selection | undefined {
    const indexes = [...this.entries].filter(entry => entry.parsed.kind === 'index');
    if (indexes.length > 1) throw new Error('Only one index route is allowed per logical parent');
    // URL pathname 保留编码，只在单条匹配器中逐段解码。
    const pathname = url.pathname.replace(/\/$/, '');
    const remaining = (pathname ? pathname.slice(1).split('/') : []).slice(this.offset);
    let selected: Selection | undefined;
    let tied = false;
    for (const entry of this.entries) {
      const match = matchRoutePath(entry.parsed, remaining);
      if (!match) continue;
      const candidate = { entry, match, identity: JSON.stringify(match.params) };
      if (!selected) { selected = candidate; continue; }
      const priority = compare(entry.parsed, selected.entry.parsed);
      if (priority === 0) tied = true;
      if (priority > 0) { selected = candidate; tied = false; }
    }
    if (tied) throw new Error(`Ambiguous route candidates for ${url.pathname}`);
    if (!selected && indexes[0]) selected = { entry: indexes[0], match: { params: {}, consumed: 0 }, identity: 'index' };
    return selected;
  }

  private reconcile(): void {
    if (this.holds.size) return;
    const url = this.location();
    const next = this.choose(url);
    if (!next) { this.clear(); return; }
    if (this.selected?.entry === next.entry && this.selected.identity === next.identity) {
      batch(() => Object.assign(this.selected!.state, { pathname: url.pathname, search: url.search, hash: url.hash }));
      this.selected.child.schedule();
      return;
    }
    try { this.clear(); } catch (error) { this.report(error); }
    const params = { ...this.parentParams, ...next.match.params };
    const state = createState<RouteContext>({ pathname: url.pathname, params, search: url.search, hash: url.hash });
    const child = new RouteGroup(this.depth + 1, this.offset + next.match.consumed, params, this.location, this.report);
    this.selected = { entry: next.entry, identity: next.identity, state, child };
    next.entry.activate({ ...next.entry.context, route: state, group: child });
    child.schedule();
  }

  private clear(): void {
    const previous = this.selected;
    this.selected = undefined;
    if (!previous) return;
    const failures: unknown[] = [];
    for (const action of [() => previous.entry.content.stopBindings(), () => previous.child.dispose(), () => previous.entry.content.dispose()]) {
      try { action(); } catch (error) { failures.push(error); }
    }
    if (failures.length) throw new AggregateError(failures, 'Route cleanup failed');
  }
  stopBindings(): void {
    const errors: unknown[] = [];
    for (const stop of [() => this.selected?.entry.content.stopBindings(), () => this.selected?.child.stopBindings()]) {
      try { stop(); } catch (error) { errors.push(error); }
    }
    if (errors.length) throw new AggregateError(errors, 'Route binding cleanup failed');
  }
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    try { this.clear(); } finally { this.entries.clear(); this.holds.clear(); }
  }
}

/** 左起比较静态/参数特异性；共同前缀相同则更长的声明优先。 */
function compare(a: ParsedRouteDeclaration, b: ParsedRouteDeclaration): number {
  if (a.kind === 'index' || b.kind === 'index') return 0;
  for (let i = 0; i < Math.min(a.segments.length, b.segments.length); i++) {
    const difference = Number(a.segments[i].kind === 'static') - Number(b.segments[i].kind === 'static');
    if (difference) return difference;
  }
  return a.segments.length - b.segments.length;
}
