const asciiWhitespace = (character: string | undefined): boolean =>
  character === ' ' || character === '\t' || character === '\n'
  || character === '\r' || character === '\f';

/**
 * 只重定位 srcset 候选的 URL，保留描述符和分隔符原文给浏览器判断。
 * token 边界遵循 WHATWG HTML 的 srcset splitting loop / descriptor tokenizer：
 * https://html.spec.whatwg.org/multipage/images.html#parse-a-srcset-attribute
 * 逗号可出现在 URL（包括 data:）内部，不能直接 split(',')。
 */
export function resolveSrcset(value: string, baseURL: string): string {
  if (typeof value !== 'string') throw new TypeError('Srcset value must be a string');
  const pieces: string[] = [];
  let position = 0;
  let preservedFrom = 0;

  while (position < value.length) {
    // 候选之间的 ASCII 空白和逗号不属于 URL；原样留在最终结果中。
    while (asciiWhitespace(value[position]) || value[position] === ',') position++;
    if (position >= value.length) break;

    const start = position;
    while (position < value.length && !asciiWhitespace(value[position])) position++;
    let end = position;
    while (value[end - 1] === ',') end--;

    const candidate = value.slice(start, end);
    let resolved: string;
    try { resolved = new URL(candidate, baseURL).href; }
    catch (cause) {
      throw new Error(`Invalid srcset URL ${JSON.stringify(candidate)} from ${JSON.stringify(baseURL)}`, { cause });
    }
    pieces.push(value.slice(preservedFrom, start), resolved);
    preservedFrom = end;

    // URL token 的尾逗号直接结束该候选，不进入 descriptor tokenizer。
    if (end !== position) continue;

    // 此处只需找描述符终点。in/after descriptor 在边界判定上等价；
    // in parens 则吞入逗号，直到第一个 ')'，不额外引入括号嵌套或引号规则。
    let inParens = false;
    while (position < value.length) {
      const character = value[position++];
      if (inParens) {
        if (character === ')') inParens = false;
      } else if (character === '(') {
        inParens = true;
      } else if (character === ',') {
        break;
      }
    }
  }

  pieces.push(value.slice(preservedFrom));
  return pieces.join('');
}
