import { Signal } from '../../state/signal.js';
import type { Scope } from '../../lifecycle/scope.js';
import { resolveSrcset } from '../resources.js';
import { unsafeNames } from './path.js';
import { writeComponentInput } from '../../component/inputs.js';

const htmlNamespace = 'http://www.w3.org/1999/xhtml';
const svgNamespace = 'http://www.w3.org/2000/svg';
const booleanTargets: Readonly<Record<string, readonly string[]>> = {
  disabled: ['button', 'input', 'select', 'textarea', 'fieldset', 'optgroup', 'option'],
  checked: ['input'], selected: ['option'], multiple: ['input', 'select'],
  readonly: ['input', 'textarea'], required: ['input', 'select', 'textarea'],
  autofocus: ['*'], inert: ['*'], itemscope: ['*'],
  open: ['details', 'dialog'], controls: ['audio', 'video'], autoplay: ['audio', 'video'],
  loop: ['audio', 'video'], muted: ['audio', 'video'], playsinline: ['video'],
  reversed: ['ol'], ismap: ['img'], novalidate: ['form'], formnovalidate: ['button', 'input'],
  allowfullscreen: ['iframe'], default: ['track'], defer: ['script'], async: ['script'],
};
const propertyNames = new Map([
  'defaultValue', 'defaultChecked', 'defaultSelected', 'indeterminate', 'scrollTop', 'scrollLeft',
  'currentTime', 'volume', 'muted', 'playbackRate', 'selectedIndex', 'valueAsNumber', 'valueAsDate',
].map(name => [name.toLowerCase(), name]));
const svgNames = new Map([
  'viewBox', 'preserveAspectRatio', 'gradientUnits', 'gradientTransform', 'patternUnits',
  'patternContentUnits', 'patternTransform', 'markerWidth', 'markerHeight', 'markerUnits',
  'refX', 'refY', 'textLength', 'lengthAdjust', 'attributeName', 'keyTimes', 'keySplines',
  'filterUnits', 'primitiveUnits', 'stdDeviation', 'baseFrequency', 'numOctaves',
  'pathLength', 'clipPathUnits', 'maskUnits', 'maskContentUnits',
].map(name => [name.toLowerCase(), name]));
const unsafeTargets = new Set(['innerhtml', 'outerhtml', 'textcontent', 'innertext', 'srcdoc']);
const globalAttributes = new Set([
  'title', 'id', 'slot', 'hidden', 'role', 'lang', 'dir', 'tabindex', 'accesskey',
  'contenteditable', 'draggable', 'spellcheck', 'translate', 'autocapitalize', 'autocorrect',
  'enterkeyhint', 'inputmode', 'is', 'nonce', 'part', 'exportparts', 'popover',
  'inert', 'autofocus', 'itemscope', 'itemid', 'itemprop', 'itemref', 'itemtype',
]);

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeTarget(element: Element, name: string): string {
  const custom = element.namespaceURI === htmlNamespace && element.localName.includes('-');
  const eventTarget = name.toLowerCase().startsWith('on')
    && (!custom || name.toLowerCase() in HTMLElement.prototype);
  if (!/^[A-Za-z_][\w:-]*$/.test(name) || unsafeNames.has(name)
    || unsafeTargets.has(name.toLowerCase()) || eventTarget
    || name.startsWith('ns-')) {
    throw new Error(`Unsupported ns-bind target: ${name}`);
  }
  if (element.namespaceURI === svgNamespace) return svgNames.get(name.toLowerCase()) ?? name;
  if (element.localName.includes('-')) return name;
  return propertyNames.get(name.toLowerCase()) ?? (/[A-Z]/.test(name) && name in element ? name : name.toLowerCase());
}

function scalar(value: unknown, target: string): string {
  if (typeof value === 'object' && value !== null || typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError(`ns-bind-${target} requires a scalar attribute value`);
  }
  return String(value);
}

/** 在 Computed 内读取对象成员，只追踪实际传给目标的字段，不做深遍历。 */
function snapshot(name: string, value: unknown): unknown {
  if ((name === 'class' || name === 'style') && record(value)) return { ...value };
  return value;
}

/** whenDefined 不能取消，释放时移除任务引用，避免未注册组件一直持有已卸载的 DOM。 */
function afterDefinition(tag: string, scope: Scope, run: () => void, report: (error: unknown) => void): void {
  const waiting: { run?: () => void; report?: (error: unknown) => void } = { run, report };
  const clear = () => { waiting.run = undefined; waiting.report = undefined; };
  const cancel = scope.add(clear);
  void customElements.whenDefined(tag).then(() => {
    try { waiting.run?.(); } catch (error) { waiting.report?.(error); }
    finally { cancel(); }
  }, error => {
    try { waiting.report?.(error); } finally { cancel(); }
  });
}

export interface ElementBindings {
  bind(name: string, read: () => unknown): void;
  bindMany(read: () => unknown): void;
  claim(name: string, owner: string): void;
}

/** 同一元素的绑定共享目标所有权；短写与对象形式使用同一写入协议。 */
export function createElementBindings(
  element: Element,
  sourceURL: string,
  scope: Scope,
  report: (error: unknown) => void,
): ElementBindings {
  const owners = new Map<string, string>();
  const writers = new Map<string, (value: unknown) => void>();
  let active = true;
  scope.add(() => { active = false; });

  function identity(name: string): string {
    const target = normalizeTarget(element, name);
    if (element.localName === 'input' && ['valueAsNumber', 'valueAsDate'].includes(target)
      || element.localName === 'select' && target === 'selectedIndex') return 'value';
    return target;
  }

  function claim(name: string, owner: string): void {
    const key = identity(name);
    const previous = owners.get(key);
    if (previous !== undefined && previous !== owner) throw new Error(`Conflicting bindings for ${name}: ${previous} and ${owner}`);
    owners.set(key, owner);
  }

  function createWriter(name: string): (value: unknown) => void {
    const tag = element.localName;
    const html = element.namespaceURI === htmlNamespace;
    if (name === 'class') {
      const baseline = new Set(element.classList);
      let previous = new Set<string>();
      return value => {
        const tokens = value == null ? [] : typeof value === 'string' ? value.split(/\s+/).filter(Boolean)
          : record(value) ? Object.keys(value).filter(key => value[key])
            : (() => { throw new TypeError('class binding requires a string or a class/boolean map'); })();
        if (tokens.some(token => /\s/.test(token))) throw new TypeError('Class map keys must be single class names');
        const next = new Set(tokens);
        for (const token of previous) if (!next.has(token) && !baseline.has(token)) element.classList.remove(token);
        for (const token of next) if (!element.classList.contains(token)) element.classList.add(token);
        previous = next;
      };
    }
    if (name === 'style') {
      const style = (element as HTMLElement | SVGElement).style;
      if (!style) throw new Error('Element does not support inline style');
      const baseline = new Map([...style].map(key => [key, [style.getPropertyValue(key), style.getPropertyPriority(key)] as const]));
      let previous = new Set<string>();
      return value => {
        const next = new Map<string, readonly [string, string]>();
        if (typeof value === 'string') {
          const parsed = document.createElement('span').style;
          parsed.cssText = value;
          for (const key of parsed) next.set(key, [parsed.getPropertyValue(key), parsed.getPropertyPriority(key)]);
        } else if (record(value)) {
          for (const [key, item] of Object.entries(value)) {
            if (item != null) next.set(key, [scalar(item, `style.${key}`), '']);
          }
        } else if (value != null) throw new TypeError('style binding requires a CSS string or a CSS property map');
        for (const key of previous) {
          if (next.has(key)) continue;
          const original = baseline.get(key);
          if (original) style.setProperty(key, original[0], original[1]);
          else style.removeProperty(key);
        }
        for (const [key, [item, priority]] of next) {
          if (style.getPropertyValue(key) !== item || style.getPropertyPriority(key) !== priority) style.setProperty(key, item, priority);
        }
        previous = new Set(next.keys());
      };
    }
    if (html && name === 'value' && ['input', 'textarea', 'select'].includes(tag)) {
      const control = element as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
      let composing = false;
      let pending = false;
      let latest: unknown;
      const apply = (value: unknown) => {
        if (tag === 'input' && (control as HTMLInputElement).type === 'file' && value != null && value !== '') {
          throw new TypeError('File input value can only be cleared');
        }
        const text = value == null ? '' : scalar(value, name);
        if (control.value !== text) control.value = text;
      };
      const start = () => { composing = true; pending = false; };
      const end = () => { composing = false; if (pending) apply(latest); pending = false; };
      element.addEventListener('compositionstart', start);
      element.addEventListener('compositionend', end);
      scope.add(() => { element.removeEventListener('compositionstart', start); element.removeEventListener('compositionend', end); });
      return value => {
        latest = value;
        if (composing) pending = true;
        else apply(value);
      };
    }
    if (html && (name === 'checked' && tag === 'input' || name === 'selected' && tag === 'option')) {
      return value => {
        if (value != null && typeof value !== 'boolean') throw new TypeError(`${name} binding requires boolean`);
        const control = element as unknown as Record<string, unknown>;
        if (control[name] !== !!value) control[name] = !!value;
      };
    }
    const globalAttribute = globalAttributes.has(name) || name.startsWith('data-') || name.startsWith('aria-');
    const controlInput = ['ns-include', 'ns-route'].includes(tag) && ['src', 'path', 'index'].includes(name);
    const customInput = html && tag.includes('-') && !controlInput && !globalAttribute;
    const nativeProperty = html && (propertyNames.get(name.toLowerCase()) === name && name in element
      || /[A-Z]/.test(name) && name in element);
    if (customInput || nativeProperty) {
      let pending = false;
      let latest: unknown;
      const apply = () => {
        if (!active) return;
        if (customInput && writeComponentInput(element, name, latest)) return;
        const target = element as unknown as Record<string, unknown>;
        if (!Object.is(target[name], latest) && !Reflect.set(element, name, latest)) {
          throw new TypeError(`DOM property is not writable: ${name}`);
        }
      };
      return value => {
        if (nativeProperty && ['defaultChecked', 'defaultSelected', 'indeterminate', 'muted'].includes(name)
          && value != null && typeof value !== 'boolean') throw new TypeError(`${name} binding requires boolean`);
        latest = value;
        if (customInput && !customElements.get(tag)) {
          if (!pending) {
            pending = true;
            afterDefinition(tag, scope, () => {
              if (!active) return;
              if (element.ownerDocument !== document) document.adoptNode(element);
              customElements.upgrade(element);
              apply();
            }, report);
          }
        } else {
          if (tag.includes('-')) {
            if (element.ownerDocument !== document) document.adoptNode(element);
            customElements.upgrade(element);
          }
          apply();
        }
      };
    }
    const boolean = html && (booleanTargets[name]?.some(item => item === '*' || item === tag)
      || tag === 'ns-route' && name === 'index');
    const namespace = name.startsWith('xlink:') ? 'http://www.w3.org/1999/xlink'
      : name.startsWith('xml:') ? 'http://www.w3.org/XML/1998/namespace' : null;
    return value => {
      let text: string | null;
      if (html && name === 'hidden') {
        if (![true, false, null, undefined, 'hidden', 'until-found'].includes(value as never)) throw new TypeError('Invalid hidden binding value');
        text = value === false || value == null ? null : value === true ? '' : String(value);
      } else if (boolean) {
        if (value != null && typeof value !== 'boolean') throw new TypeError(`${name} binding requires boolean`);
        text = value ? '' : null;
      } else text = value == null ? null : scalar(value, name);
      if (text !== null) {
        if (isURLTarget(element, name) && !text.startsWith('#')) text = new URL(text, sourceURL).href;
        if (name === 'srcset' && ['img', 'source'].includes(tag) || name === 'imagesrcset' && tag === 'link') {
          text = resolveSrcset(text, sourceURL);
        }
      }
      if (['ns-include', 'ns-route'].includes(tag) && name === 'src' && (value == null || !String(value).trim())) {
        throw new TypeError(`${tag}.src requires a non-empty URL`);
      }
      const localName = namespace ? name.slice(name.indexOf(':') + 1) : name;
      const current = namespace ? element.getAttributeNS(namespace, localName) : element.getAttribute(name);
      if (current === text) return;
      if (text === null) element.removeAttributeNS(namespace, localName);
      else element.setAttributeNS(namespace, name, text);
    };
  }

  function write(name: string, value: unknown): void {
    let writer = writers.get(name);
    if (!writer) { writer = createWriter(name); writers.set(name, writer); }
    writer(value);
  }

  return {
    claim,
    bind(name, read) {
      const target = normalizeTarget(element, name);
      claim(target, `ns-bind-${name}`);
      scope.add(new Signal.Computed(() => snapshot(target, read())).subscribe(value => write(target, value)));
    },
    bindMany(read) {
      let previous = new Set<string>();
      const values = new Signal.Computed(() => {
        const value = read();
        if (!record(value)) throw new TypeError('ns-bind requires an object of target/value entries');
        return Object.entries(value).map(([key, item]) => {
          const name = normalizeTarget(element, key);
          return [name, snapshot(name, item)] as const;
        });
      });
      scope.add(values.subscribe(entries => {
        const next = new Set<string>();
        for (const [name] of entries) {
          const key = identity(name);
          if (next.has(key)) throw new Error(`Duplicate ns-bind target: ${name}`);
          next.add(key);
          const previousOwner = owners.get(key);
          if (previousOwner !== undefined && previousOwner !== 'ns-bind') {
            throw new Error(`Conflicting bindings for ${name}: ${previousOwner} and ns-bind`);
          }
        }
        for (const name of previous) {
          if (!entries.some(([key]) => key === name)) {
            write(name, undefined);
            owners.delete(identity(name));
          }
        }
        for (const [name] of entries) claim(name, 'ns-bind');
        // 决定控件协议的配置先写，当前值最后写；不依赖对象键的声明顺序。
        const priority = (name: string) => ['type', 'multiple', 'defaultValue', 'defaultChecked', 'defaultSelected'].includes(name) ? 0 : ['value', 'checked', 'selected'].includes(name) ? 2 : 1;
        for (const [name, value] of [...entries].sort((a, b) => priority(a[0]) - priority(b[0]))) write(name, value);
        previous = new Set(entries.map(([name]) => name));
      }));
    },
  };
}

function isURLTarget(element: Element, name: string): boolean {
  const tag = element.localName;
  if (name === 'src') return ['img', 'audio', 'video', 'source', 'track', 'input', 'iframe', 'embed', 'ns-include', 'ns-route'].includes(tag);
  if (name === 'href' || name === 'xlink:href') return ['a', 'area', 'link', 'use', 'image'].includes(tag);
  if (name === 'poster') return tag === 'video';
  if (name === 'action') return tag === 'form';
  if (name === 'formaction') return tag === 'input' || tag === 'button';
  return name === 'data' && tag === 'object';
}
