function reportUnhandled(error: unknown): void {
  if (typeof globalThis.reportError === 'function') globalThis.reportError(error);
  else setTimeout(() => { throw error; }, 0);
}

/** 保护用户错误回调；包括回调自身的异步拒绝，不产生悬空 Promise。 */
export function createErrorReporter(onError?: (error: unknown) => void): (error: unknown) => void {
  if (onError !== undefined && typeof onError !== 'function') {
    throw new TypeError('onError must be a function');
  }
  if (!onError) return reportUnhandled;
  return error => {
    const reportFailure = (handlerError: unknown) => reportUnhandled(
      new AggregateError([error, handlerError], 'Binding error handler failed'),
    );
    try {
      const result: unknown = onError(error);
      if (result !== null && (typeof result === 'object' || typeof result === 'function')) {
        void Promise.resolve(result).catch(reportFailure);
      }
    } catch (handlerError) {
      reportFailure(handlerError);
    }
  };
}
