import { Signal } from '../state/signal.js';
import { emptyInputs, initialValue, parseAttribute, serializeAttribute } from './fields.js';
import type { ComponentFields, FieldDefinition, InputReferences } from './fields.js';

const ports = new WeakMap<Element, ComponentInputs>();

export function validateHostFields(definitions: ComponentFields): void {
  for (const kind of ['properties', 'attributes'] as const) {
    for (const [name, definition] of Object.entries(definitions[kind])) {
      if ((kind === 'properties' || definition.reflect)
        && (name in HTMLElement.prototype || /^(?:connected|disconnected|adopted|attributeChanged|connectedMove)Callback$/.test(name))) {
        throw new TypeError(`Component property conflicts with the host: ${name}`);
      }
    }
  }
}

/** Binding uses this protocol for both registered names and ns-include. */
export function writeComponentInput(element: Element, name: string, value: unknown): boolean {
  const port = ports.get(element);
  if (!port) return false;
  port.write(name, value);
  return true;
}

interface Input {
  readonly name: string;
  readonly definition: FieldDefinition;
  readonly signal: InstanceType<typeof Signal.State<unknown>>;
  readonly propertyName?: string;
  readonly attributeName?: string;
  lastAttribute: string | null;
  getProperty?: () => unknown;
}

export class ComponentInputs {
  properties: InputReferences = emptyInputs;
  attributes: InputReferences = emptyInputs;
  private fields?: Map<string, Input>;
  private readonly pending = new Map<string, unknown>();
  private observer?: MutationObserver;
  private syncing = false;
  private readonly detached = new Map<string, () => unknown>();

  constructor(private readonly element: HTMLElement, private readonly report: (error: unknown) => void) {
    ports.set(element, this);
  }

  write(name: string, value: unknown): void {
    if (!this.fields) {
      this.pending.set(name, value);
      Reflect.set(this.element, name, value);
      return;
    }
    const input = this.fields.get(name.toLowerCase());
    if (!input) throw new Error(`Unknown component input ${name} on <${this.element.localName}>`);
    this.syncAttributes();
    this.set(input, value, true);
  }

  configure(definitions: ComponentFields): void {
    this.fields = new Map();
    const properties: Record<string, InputReferences[string]> = Object.create(null);
    const attributes: Record<string, InputReferences[string]> = Object.create(null);
    try {
      validateHostFields(definitions);
      const propertyNames = new Set([
        ...Object.keys(definitions.properties),
        ...Object.entries(definitions.attributes).filter(([, definition]) => definition.reflect).map(([name]) => name),
      ]);
      for (const [name, getter] of this.detached) {
        if (!propertyNames.has(name)) {
          if (Object.getOwnPropertyDescriptor(this.element, name)?.get === getter) Reflect.deleteProperty(this.element, name);
          this.detached.delete(name);
        }
      }
      for (const kind of ['properties', 'attributes'] as const) {
        const declarations = definitions[kind];
        for (const [name, definition] of Object.entries(declarations)) {
          const propertyName = kind === 'properties' || definition.reflect ? name : undefined;
          const attributeName = kind === 'attributes' || definition.reflect ? name.toLowerCase() : undefined;
          let value = initialValue(definition);
          const raw = attributeName ? this.element.getAttribute(attributeName) : null;
          if (raw !== null) value = parseAttribute(definition, raw);
          const pendingName = [...this.pending.keys()].find(key => key.toLowerCase() === name.toLowerCase());
          const ownName = Object.hasOwn(this.element, name) ? name : pendingName;
          const hasOwn = ownName !== undefined && Object.hasOwn(this.element, ownName);
          if (hasOwn) value = Reflect.get(this.element, ownName!);
          else if (pendingName !== undefined) value = this.pending.get(pendingName);
          const input: Input = { name, definition, signal: new Signal.State(value), propertyName, attributeName, lastAttribute: raw };
          this.fields.set(name.toLowerCase(), input);
          if (hasOwn && !Reflect.deleteProperty(this.element, ownName!)) throw new TypeError(`Component input is not configurable: ${name}`);
          if (propertyName) {
            input.getProperty = () => input.signal.get();
            Object.defineProperty(this.element, propertyName, {
              configurable: true, enumerable: true,
              get: input.getProperty,
              set: value => { this.syncAttributes(); this.set(input, value, true); },
            });
            this.detached.delete(propertyName);
          }
          const reference = Object.freeze({
            get: () => input.signal.get(), peek: () => input.signal.peek(),
            subscribe: (listener: (value: unknown) => void) => input.signal.subscribe(listener),
          });
          (kind === 'properties' ? properties : attributes)[name] = reference;
          // Explicit inputs may reflect; defaults remain off the DOM until written.
          if (hasOwn || pendingName !== undefined) this.set(input, value, true);
        }
      }
      for (const name of this.pending.keys()) {
        if (!this.fields.has(name.toLowerCase())) throw new Error(`Unknown component input ${name} on <${this.element.localName}>`);
      }
      this.pending.clear();
      this.properties = Object.freeze(properties);
      this.attributes = Object.freeze(attributes);
      const filter = [...this.fields.values()].flatMap(input => input.attributeName ? [input.attributeName] : []);
      if (filter.length) {
        this.observer = new MutationObserver(() => this.syncAttributes());
        this.observer.observe(this.element, { attributes: true, attributeFilter: filter });
      }
    } catch (error) {
      this.dispose();
      throw error;
    }
  }

  private set(input: Input, value: unknown, reflect: boolean): void {
    if (value === undefined) value = initialValue(input.definition);
    if (input.attributeName && reflect) {
      const text = serializeAttribute(input.definition, value);
      input.lastAttribute = text;
      if (this.element.getAttribute(input.attributeName) !== text) {
        if (text === null) this.element.removeAttribute(input.attributeName);
        else this.element.setAttribute(input.attributeName, text);
      }
    }
    input.signal.set(value);
  }

  private syncAttributes(): void {
    if (this.syncing || !this.fields) return;
    this.syncing = true;
    this.observer?.takeRecords();
    try {
      for (const input of this.fields.values()) {
        if (!input.attributeName) continue;
        const value = this.element.getAttribute(input.attributeName);
        if (value === input.lastAttribute) continue;
        input.lastAttribute = value;
        try { this.set(input, parseAttribute(input.definition, value), false); }
        catch (cause) { this.report(new Error(`Invalid component attribute ${input.attributeName} on <${this.element.localName}>`, { cause })); }
      }
    } finally { this.syncing = false; }
  }

  stop(): void { this.observer?.disconnect(); this.observer = undefined; }

  dispose(): void {
    this.stop();
    for (const input of this.fields?.values() ?? []) {
      if (!input.propertyName || Object.getOwnPropertyDescriptor(this.element, input.propertyName)?.get !== input.getProperty) continue;
      // Keep DOM inputs while detached without retaining the old instance's Signal or subscriptions.
      const { definition, attributeName, propertyName } = input;
      const element = this.element;
      let value = input.signal.peek();
      let raw = input.lastAttribute;
      const get = () => {
        if (attributeName) {
          const current = element.getAttribute(attributeName);
          if (current !== raw) { value = parseAttribute(definition, current); raw = current; }
        }
        return value;
      };
      Object.defineProperty(element, propertyName, {
        configurable: true, enumerable: true, get,
        set(next: unknown) {
          if (next === undefined) next = initialValue(definition);
          if (attributeName) {
            const text = serializeAttribute(definition, next);
            if (text === null) element.removeAttribute(attributeName);
            else if (element.getAttribute(attributeName) !== text) element.setAttribute(attributeName, text);
            raw = text;
          }
          value = next;
        },
      });
      this.detached.set(propertyName, get);
    }
    this.fields = undefined;
    this.properties = emptyInputs;
    this.attributes = emptyInputs;
  }
}
