/** 共享组件定义的准备与缓存，以及每个宿主独立拥有的内容加载和清理。 */
import { loadTemplateSource } from '../template/source.js';
import { parseTemplateFragment } from '../template/fragment.js';
import { resolveSrcset } from '../template/resources.js';
import { instantiateTemplate, prepareTemplateDefinition } from '../template/view.js';
import type { PreparedTemplateDefinition, PreparedTemplateView, TemplateViewOptions } from '../template/view.js';
import type { TemplateSource } from '../template/source.js';
import type { ContentContext, ManagedResource } from './context.js';
import { ComponentInputs, validateHostFields } from '../component/inputs.js';
import { prepareHostActions } from '../component/actions.js';

/** 可跨宿主复用的定义；不包含任何宿主的 DOM、本地状态或订阅。 */
export interface ComponentTemplate {
    readonly source: TemplateSource;
    readonly definition: PreparedTemplateDefinition;
}

interface DefinitionEntry {
    /** 共享准备任务的取消信号，不直接绑定到某一个消费者。 */
    readonly controller: AbortController;
    promise: Promise<ComponentTemplate>;
    /** 仍在等待该 Promise 的消费者数；成功定义的缓存寿命不由此计数决定。 */
    users: number;
    /** 成功或失败后均为 true，只有未完成的任务才需要取消。 */
    settled: boolean;
}
const definitions = new Map<string, DefinitionEntry>();

/** 成功定义持续缓存；未完成任务只在最后一个等待者退出时取消，失败可重试。 */
export function loadComponentTemplate(url: string, signal?: AbortSignal): Promise<ComponentTemplate> {
    signal?.throwIfAborted();
    // hash 不参与资源身份；query 仍保留，可用于区分不同版本的定义。
    const reference = new URL(url);
    reference.hash = '';
    const key = reference.href;
    let entry = definitions.get(key);
    if (!entry) {
        const controller = new AbortController();
        entry = { controller, users: 0, settled: false, promise: Promise.resolve(undefined as never) };
        const current = entry;
        entry.promise = (async () => {
            // 这里只准备 HTML、模块与字段描述；本地 Behavior 在各宿主实例化时才调用。
            const source = await loadTemplateSource(key, { baseURL: key, signal: controller.signal });
            const parsed = parseTemplateFragment(source.html, source.url);
            prepareMarkup(parsed.content, source.url);
            const definition = await prepareTemplateDefinition(parsed, new Set(), controller.signal);
            validateHostFields(definition.fields);
            current.settled = true;
            // 最终 URL 尚无缓存时，将它作为同一条目的别名，供后续直接引用复用。
            if (!definitions.has(source.url)) definitions.set(source.url, current);
            return Object.freeze({ source, definition });
        })().catch(error => {
            current.settled = true;
            // 旧任务失败时不能删除已经替换为新任务的条目。
            if (definitions.get(key) === current) definitions.delete(key);
            throw error;
        });
        definitions.set(key, entry);
    }
    const current = entry;
    current.users++;
    return new Promise((resolve, reject) => {
        // 每个调用方有独立的完成标记；取消与共享任务兑现最多释放一次持有。
        let done = false;
        const release = () => {
            if (done) return false;
            done = true;
            signal?.removeEventListener('abort', abort);
            if (--current.users === 0 && !current.settled) {
                // 单个调用方退出不影响其他等待者，全部退出后才中止共享加载。
                if (definitions.get(key) === current) definitions.delete(key);
                current.controller.abort();
            }
            return true;
        };
        const abort = () => { if (release()) reject(signal!.reason); };
        signal?.addEventListener('abort', abort, { once: true });
        current.promise.then(value => { if (release()) resolve(value); }, error => { if (release()) reject(error); });
        // 补查订阅前已经发生的取消，避免漏掉当前调用方的终止状态。
        if (signal?.aborted) abort();
    });
}

/** 组件内容控制器；管理一个宿主元素的当前组件实例，本身不是宿主元素或公开实例 API。
 * include、注册标签与已命中 route 共用此加载流程；路由匹配由外部决定。 */
export class ComponentController implements ManagedResource {
    /** 输入连接归宿主所有，定义缓存只保存字段描述。 */
    private readonly inputs: ComponentInputs;
    /** 组件内部 DOM 的浏览器边界；外层宿主元素为 element。 */
    get shadowRoot(): ShadowRoot {
        return this.element.shadowRoot ?? this.element.attachShadow({ mode: 'open' });
    }
    /** 仅代表当前宿主自身的加载与绑定，不等待所有后代或整个路由树。 */
    ready: Promise<void> = Promise.resolve();
    /** 同时用于取消加载与辨认当前加载轮次，阻止旧结果覆盖新内容。 */
    private abort?: AbortController;
    private view?: PreparedTemplateView;
    private actions?: ReturnType<typeof prepareHostActions>;
    private releaseHold?: () => void;
    constructor(
        readonly element: HTMLElement,
        private prepareChild: (element: Element, context: ContentContext) => ManagedResource | void,
        private report: (element: HTMLElement, error: unknown) => void,
    ) { this.inputs = new ComponentInputs(element, error => report(element, error)); }

    load(context: ContentContext, templateURL?: string): void {
        // src 切换与重新加载都先完整退出上一轮内容。
        this.dispose();
        const abort = new AbortController();
        this.abort = abort;
        // 加载中的模板可能继续声明路由，所属候选组需等待这一轮准备完成。
        const hold = context.group.hold();
        this.releaseHold = hold.release;
        const active = () => this.abort === abort && !abort.signal.aborted && this.element.isConnected;
        let ownedView: PreparedTemplateView | undefined;
        let ownedActions: ReturnType<typeof prepareHostActions> | undefined;
        let mounting = false;
        this.ready = (async () => {
            const reference = templateURL ?? this.element.getAttribute('src');
            if (!reference?.trim()) throw new TypeError('Template src must be a non-empty string');
            const requested = new URL(reference, context.baseURL);
            requested.hash = '';
            // 请求地址和实际重定向链都检查，避免通过不同 URL 绕过循环检测。
            if (context.ancestors.includes(requested.href)) throw new Error(`Circular Template: ${[...context.ancestors, requested.href].join(' -> ')}`);
            const { source, definition } = await loadComponentTemplate(requested.href, abort.signal);
            if (!active()) return;
            if (source.ancestors.some(url => context.ancestors.includes(url))) {
                throw new Error(`Circular Template: ${[...context.ancestors, ...source.ancestors].join(' -> ')}`);
            }
            // 在调用 Behavior 前接入声明字段及加载期间写入的最新输入。
            this.inputs.configure(definition.fields);
            // 两种入口都建立独立的组件上下文：不继承调用方的本地状态或循环变量，数据由输入连接。
            const childContext: ContentContext = {
                ...context, baseURL: source.url,
                ancestors: [...context.ancestors, ...source.ancestors],
                variables: undefined,
                properties: this.inputs.properties, attributes: this.inputs.attributes,
            };
            const bindings = {
                acquireBehavior: context.acquireBehavior, route: context.route,
                properties: this.inputs.properties, attributes: this.inputs.attributes,
            };
            const options: TemplateViewOptions = {
                signal: abort.signal,
                onError: (error: unknown) => this.report(this.element, error),
                // 节点挂载前交给调用区域持有，传递输入绑定与循环变量；不传递父组件本地结果。
                onElement: (element, _local, bindings) => this.prepareChild(element, { ...childContext, ...bindings }),
            };
            const view = instantiateTemplate(definition, bindings, options);
            ownedView = view;
            // Behavior 初始化可能同步触发宿主退出，已创建的视图也必须回收。
            if (!active()) { view.dispose(); return; }
            this.view = view;
            ownedActions = prepareHostActions(this.element, view.actions, definition.fields, source.url);
            this.actions = ownedActions;
            mounting = true;
            view.mount(this.shadowRoot);
            if (!active()) { ownedActions.dispose(); return; }
            ownedActions.install();
            hold.settle();
        })().catch(error => {
            // 加载取消仍可正常结算；挂载回调退出后抛出的错误必须保留，不能清理替代实例。
            if (!active()) { if (mounting) throw error; return; }
            // 保留失败占用，不能将缺失的路由候选误判为未匹配并进入 index。
            hold.fail();
            const failures = [error];
            if (this.view === ownedView) this.view = undefined;
            if (this.actions === ownedActions) this.actions = undefined;
            try { ownedActions?.dispose(); } catch (cleanup) { failures.push(cleanup); }
            try { ownedView?.dispose(); } catch (cleanup) { failures.push(cleanup); }
            if (active()) {
                try { this.inputs.dispose(); } catch (cleanup) { failures.push(cleanup); }
                this.shadowRoot.replaceChildren();
            }
            throw new AggregateError(failures, `Template load failed at ${templateURL ?? this.element.getAttribute('src')} (from ${context.baseURL})`);
        });
        void this.ready.catch(error => this.report(this.element, error));
    }

    stopBindings(): void {
        // 清理分两阶段：先停止响应式写入，完整 dispose 再释放实例与 DOM。
        const errors: unknown[] = [];
        for (const stop of [() => this.actions?.dispose(), () => this.inputs.stop(), () => { if (!this.view) this.abort?.abort(); }, () => this.view?.stopBindings()]) {
            try { stop(); } catch (error) { errors.push(error); }
        }
        if (errors.length) throw new AggregateError(errors, 'Template stop failed');
    }
    dispose(): void {
        // 先摘除自身句柄，再执行可能触发回调的清理，避免重复使用这一轮资源。
        const view = this.view;
        this.view = undefined;
        const actions = this.actions;
        this.actions = undefined;
        const abort = this.abort;
        this.abort = undefined;
        const releaseHold = this.releaseHold;
        this.releaseHold = undefined;
        const errors: unknown[] = [];
        // 即使某一项清理失败，也继续释放输入、加载占用及 DOM，并保留全部异常。
        for (const cleanup of [() => actions?.dispose(), () => this.inputs.stop(), () => view?.dispose(), () => this.inputs.dispose(), () => abort?.abort(), () => releaseHold?.(), () => this.element.shadowRoot?.replaceChildren()]) {
            try { cleanup(); } catch (error) { errors.push(error); }
        }
        if (errors.length) throw new AggregateError(errors, 'Template cleanup failed');
    }
}

/** 在共享定义阶段校验模板标记并解析资源地址；这里尚未连接到文档。 */
function prepareMarkup(content: DocumentFragment, sourceURL: string): void {
    for (const element of content.querySelectorAll('*')) {
        // 合法的 Behavior 脚本已由片段解析器提取，剩余 script 不属于执行协议。
        if (element.localName === 'script') throw new Error(`Template scripts must use inline <script ns-behavior type="module">: ${sourceURL}`);
        if (element.localName === 'base') throw new Error(`Template must not declare a document base URL: ${sourceURL}`);
        if (element.localName === 'ns-include' || element.localName === 'ns-route') {
            if (element.hasAttribute('behavior')) throw new Error(`Declare Behavior inside the Template, not on ${element.localName}: ${sourceURL}`);
            if (element.localName === 'ns-route' && [...element.childNodes].some(node => node.nodeType !== Node.COMMENT_NODE && (node.nodeType !== Node.TEXT_NODE || node.textContent?.trim()))) {
                throw new Error(`${element.localName} content must be provided through src: ${sourceURL}`);
            }
        }
        // HTML 单 URL 属性按来源解析；CSS 标签/属性保持浏览器原文。
        const names: string[] = [];
        if (['img', 'audio', 'video', 'source', 'track', 'input', 'iframe', 'embed'].includes(element.localName)) names.push('src');
        if (['a', 'area', 'link', 'use', 'image'].includes(element.localName)) names.push('href');
        if (element.localName === 'video') names.push('poster');
        if (element.localName === 'form') names.push('action');
        if (element.localName === 'input' || element.localName === 'button') names.push('formaction');
        if (element.localName === 'object') names.push('data');
        for (const name of names) {
            const value = element.getAttribute(name);
            // 文档内锚点保留原生意义，页面导航交给路由入口处理。
            if (value !== null && !value.startsWith('#')) element.setAttribute(name, new URL(value, sourceURL).href);
        }
        const candidates = ['img', 'source'].includes(element.localName) ? ['srcset'] : element.localName === 'link' ? ['imagesrcset'] : [];
        for (const name of candidates) {
            if (element.hasAttribute(name)) element.setAttribute(name, resolveSrcset(element.getAttribute(name)!, sourceURL));
        }
        if (element.localName === 'template' && ['ns-foreach', 'ns-if', 'ns-else-if', 'ns-else'].some(name => element.hasAttribute(name))) {
            // querySelectorAll 不进入 template.content，结构分支的惰性内容需递归准备。
            prepareMarkup((element as HTMLTemplateElement).content, sourceURL);
        }
    }
}
