export type TextSegment =
  | { readonly kind: 'text'; readonly value: string }
  | { readonly kind: 'binding'; readonly path: string };

/** 一次性解析文本中的 {{ state.path }}；反斜杠转义起始双括号，不执行 JavaScript。 */
export function parseTextSegments(source: string): readonly TextSegment[] {
  const parts: TextSegment[] = [];
  let cursor = 0;
  let literal = '';
  while (cursor < source.length) {
    const start = source.indexOf('{{', cursor);
    if (start === -1) {
      literal += source.slice(cursor);
      break;
    }
    if (start > cursor && source[start - 1] === '\\') {
      literal += source.slice(cursor, start - 1) + '{{';
      cursor = start + 2;
      continue;
    }
    literal += source.slice(cursor, start);
    if (literal) parts.push({ kind: 'text', value: literal });
    literal = '';
    const end = source.indexOf('}}', start + 2);
    if (end === -1) throw new Error(`Unclosed text interpolation: ${source.slice(start)}`);
    const path = source.slice(start + 2, end);
    parts.push({ kind: 'binding', path });
    cursor = end + 2;
  }
  if (literal) parts.push({ kind: 'text', value: literal });
  return parts;
}
