import { createBehaviorInstance } from './instance.js';
import type { Behavior, BehaviorInstance, BehaviorLease } from './types.js';

export interface BehaviorRegistry {
  register(name: string, behavior: Behavior): void;
  acquire(name: string): BehaviorLease;
}

interface Entry {
  readonly name: string;
  readonly dependencies: Set<string>;
  phase: 'creating' | 'ready' | 'disposing';
  instance?: BehaviorInstance;
  references: number;
}

const identifier = /^[A-Za-z_$][\w$]*$/;
const reserved = new Set(['state', 'actions', '__proto__', 'prototype', 'constructor']);

function validateName(name: string): void {
  if (typeof name !== 'string' || !identifier.test(name) || reserved.has(name)) {
    throw new Error(`Invalid business Behavior name: ${String(name)}`);
  }
}

/**
 * 定义登记与实例寿命分离。并存使用者共享实例，最后一份引用释放时同步销毁。
 * 依赖关系也持有引用；同时检测初始化时及动作执行中建立的循环依赖。
 */
export function createBehaviorRegistry(): BehaviorRegistry {
  const definitions = new Map<string, Behavior>();
  const active = new Map<string, Entry>();
  const constructing: string[] = [];

  function pathTo(start: string, target: string, seen = new Set<string>()): string[] | undefined {
    if (start === target) return [start];
    if (seen.has(start)) return undefined;
    seen.add(start);
    for (const dependency of active.get(start)?.dependencies ?? []) {
      const path = pathTo(dependency, target, seen);
      if (path) return [start, ...path];
    }
    return undefined;
  }

  function acquireDependency(owner: Entry, name: string): BehaviorLease {
    validateName(name);
    const cycle = pathTo(name, owner.name);
    if (cycle) throw new Error(`Circular Behavior dependency: ${[owner.name, ...cycle].join(' -> ')}`);
    owner.dependencies.add(name);
    let lease: BehaviorLease;
    try { lease = acquire(name); }
    catch (error) { owner.dependencies.delete(name); throw error; }
    let released = false;
    return Object.freeze({
      value: lease.value,
      release() {
        if (released) return;
        released = true;
        owner.dependencies.delete(name);
        lease.release();
      },
    });
  }

  function acquire(name: string): BehaviorLease {
    validateName(name);
    const definition = definitions.get(name);
    if (!definition) throw new Error(`Unknown business Behavior: ${name}`);
    let entry = active.get(name);
    if (entry?.phase === 'creating') {
      throw new Error(`Circular Behavior initialization: ${[...constructing, name].join(' -> ')}`);
    }
    if (entry?.phase === 'disposing') throw new Error(`Business Behavior is being disposed: ${name}`);
    if (!entry) {
      entry = { name, dependencies: new Set(), phase: 'creating', references: 0 };
      active.set(name, entry);
      const owner = entry;
      constructing.push(name);
      try {
        entry.instance = createBehaviorInstance(definition, {
          acquireBehavior: dependency => acquireDependency(owner, dependency),
        });
        entry.phase = 'ready';
      } catch (error) {
        active.delete(name);
        throw error;
      } finally { constructing.pop(); }
    }
    entry.references++;
    const retained = entry;
    let released = false;
    return Object.freeze({
      value: retained.instance!.value,
      release() {
        if (released) return;
        released = true;
        retained.references--;
        if (retained.references !== 0) return;
        retained.phase = 'disposing';
        try { retained.instance!.dispose(); }
        finally {
          // 清理失败也不留下无法再次创建的条目。
          active.delete(name);
          retained.dependencies.clear();
        }
      },
    });
  }

  return Object.freeze({
    register(name: string, behavior: Behavior) {
      validateName(name);
      if (typeof behavior !== 'function') throw new TypeError(`Business Behavior must be a function: ${name}`);
      if (definitions.has(name)) throw new Error(`Duplicate business Behavior: ${name}`);
      definitions.set(name, behavior);
    },
    acquire,
  });
}
