import type { BehaviorResult } from '../behavior/types.js';
import type { ComponentFields } from './fields.js';

/** 将组件 Behavior 的动作发布到宿主元素；每个组件实例独立持有并清理方法包装。 */
export function prepareHostActions(host: HTMLElement, actions: BehaviorResult['actions'] | undefined, fields: ComponentFields, source: string) {
  const inputs = new Set([...Object.keys(fields.properties), ...Object.keys(fields.attributes)].map(name => name.toLowerCase()));
  const reserved = new Set(['__proto__', 'constructor', 'prototype', 'src', 'ready', 'path', 'index']);
  const methods = Object.entries(actions ?? {}).map(([name, fn]) => {
    const label = `Component action ${name} at ${source}`;
    if (!/^[A-Za-z_]\w*$/.test(name) || reserved.has(name.toLowerCase()) || inputs.has(name.toLowerCase())) {
      throw new TypeError(`${label}: reserved or conflicting name`);
    }
    if (typeof fn !== 'function') throw new TypeError(`${label} must be a function`);
    const cell: { fn: typeof fn | undefined } = { fn };
    // 只捕获单个实现槽与诊断字符串，旧包装不持有整个宿主控制器。
    const wrapper = function(this: unknown, ...args: unknown[]) {
      if (!cell.fn) throw new Error(`${label}: instance has been disposed`);
      return Reflect.apply(cell.fn, this, args);
    };
    return { name, cell, wrapper, label };
  });
  let disposed = false;
  const validate = () => {
    for (const method of methods) if (method.name in host) throw new TypeError(`${method.label}: conflicts with host member`);
  };
  validate();
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    for (const method of methods) method.cell.fn = undefined;
    const errors: unknown[] = [];
    for (const method of methods) {
      try {
        if (Object.getOwnPropertyDescriptor(host, method.name)?.value === method.wrapper && !Reflect.deleteProperty(host, method.name)) {
          throw new TypeError(`${method.label}: cannot remove host method`);
        }
      } catch (error) { errors.push(error); }
    }
    if (errors.length) throw new AggregateError(errors, `Component action cleanup failed at ${source}`);
  };
  return {
    dispose,
    install() {
      if (disposed) throw new Error(`Component actions have been disposed at ${source}`);
      try {
        validate();
        for (const { name, wrapper } of methods) {
          Object.defineProperty(host, name, { value: wrapper, enumerable: false, writable: false, configurable: true });
        }
      } catch (error) {
        try { dispose(); } catch (cleanup) { throw new AggregateError([error, cleanup], `Component action installation failed at ${source}`); }
        throw error;
      }
    },
  };
}
