import type { Behavior } from './types.js';

interface DefinitionEntry {
  readonly source: string;
  readonly promise: Promise<ModuleFunction>;
}

type ModuleFunction = (...args: never[]) => unknown;

// 每个来源只保存当前文本的定义。不能依赖 revokeObjectURL 清除浏览器的 module map。
const definitions = new Map<string, DefinitionEntry>();

/**
 * 浏览器原生内联模块载体。只提取默认导出，不执行 Behavior 初始化。
 * 不改写 import；导入说明符必须符合内联模块的原生解析约定。
 * 同来源、同文本共享模块定义及导入 Promise，模块顶层按定义求值。
 * 每次区域初始化仍调用返回函数；私有可变状态应在函数内部创建。
 */
export function loadInlineBehavior(source: string, sourceURL: string): Promise<Behavior> {
  return loadInlineFunction<Behavior>(source, sourceURL, 'Behavior');
}

/** Behavior 与生成的事件工厂共享原生 Blob ESM 载体，不引入 eval 或应用构建步骤。 */
export function loadInlineFunction<Definition extends ModuleFunction>(
  source: string,
  sourceURL: string,
  kind = 'Template',
): Promise<Definition> {
  if (typeof source !== 'string') return Promise.reject(new TypeError(`Inline ${kind} source must be a string`));
  if (typeof sourceURL !== 'string' || !sourceURL.trim()) {
    return Promise.reject(new TypeError(`Inline ${kind} source URL must be a non-empty string`));
  }
  const key = `${kind}\0${sourceURL}`;
  const current = definitions.get(key);
  if (current?.source === source) return current.promise as Promise<Definition>;

  const entry: DefinitionEntry = {
    source,
    promise: importDefinition(source, sourceURL, kind).catch(error => {
      // 较旧文本的失败不能删掉同来源后来登记的定义；失败本身允许下次重试。
      if (definitions.get(key) === entry) definitions.delete(key);
      throw error;
    }),
  };
  definitions.set(key, entry);
  return entry.promise as Promise<Definition>;
}

async function importDefinition(source: string, sourceURL: string, kind: string): Promise<ModuleFunction> {
  let moduleURL: string | undefined;
  try {
    // 保留来源用于调试；编码换行等字符，来源不能注入额外脚本或注释行。
    const label = encodeURI(sourceURL);
    const blob = new Blob([source, `\n//# sourceURL=${label}\n`], { type: 'text/javascript' });
    moduleURL = URL.createObjectURL(blob);
    const module: { default?: unknown } = await import(/* @vite-ignore */ moduleURL);
    if (typeof module.default !== 'function') {
      throw new TypeError(`Inline ${kind} module must default-export a function`);
    }
    return module.default as ModuleFunction;
  } catch (cause) {
    throw new Error(`Failed to load inline ${kind} from ${sourceURL}`, { cause });
  } finally {
    // 撤销资源 URL 不撤销已经加载的模块和函数；后续导入仍由浏览器原生解析。
    if (moduleURL !== undefined) URL.revokeObjectURL(moduleURL);
  }
}
