import type { Readable } from '../state/signal.js';

export interface FieldOptions {
  readonly reflect?: boolean;
}

const fieldBrand = Symbol('nanshann.field');

/** Shared input metadata. Signals are created separately for each component instance. */
export interface FieldDefinition<T = unknown> {
  readonly [fieldBrand]: true;
  readonly kind: 'property' | 'attribute';
  readonly defaultValue: T;
  readonly reflect: boolean;
}

export type FieldDefinitions = Readonly<Record<string, FieldDefinition>>;
export type InputReferences = Readonly<Record<string, Readable<unknown>>>;
export type InputsOf<Fields extends FieldDefinitions> = {
  readonly [Key in keyof Fields]: Readable<Fields[Key]['defaultValue']>;
};

function field<T>(kind: FieldDefinition['kind'], defaultValue: T, options: FieldOptions): FieldDefinition<T> {
  if (!options || typeof options !== 'object' || Array.isArray(options)
    || Object.keys(options).some(key => key !== 'reflect')
    || options.reflect !== undefined && typeof options.reflect !== 'boolean') {
    throw new TypeError('Input options support a boolean reflect flag');
  }
  if ((kind === 'attribute' || options.reflect) && !isScalar(defaultValue)) {
    throw new TypeError('Attributes and reflected properties require a string, boolean or finite number default');
  }
  return Object.freeze({ [fieldBrand]: true as const, kind, defaultValue, reflect: options.reflect ?? false });
}

export function property<T>(defaultValue: T, options: FieldOptions = {}): FieldDefinition<T> {
  return field('property', defaultValue, options);
}

export function attribute(defaultValue: string, options?: FieldOptions): FieldDefinition<string>;
export function attribute(defaultValue: number, options?: FieldOptions): FieldDefinition<number>;
export function attribute(defaultValue: boolean, options?: FieldOptions): FieldDefinition<boolean>;
export function attribute(defaultValue: string | number | boolean, options?: FieldOptions): FieldDefinition<string | number | boolean>;
export function attribute(defaultValue: string | number | boolean, options: FieldOptions = {}): FieldDefinition<string | number | boolean> {
  return field('attribute', defaultValue, options);
}

function isScalar(value: unknown): value is string | number | boolean {
  return typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number' && Number.isFinite(value);
}

export interface ComponentFields {
  readonly properties: FieldDefinitions;
  readonly attributes: FieldDefinitions;
}

export const emptyFields: ComponentFields = Object.freeze({ properties: Object.freeze({}), attributes: Object.freeze({}) });
export const emptyInputs: InputReferences = Object.freeze({});

/** Snapshot metadata once, before any Behavior invocation. */
export function readComponentFields(behavior: { properties?: FieldDefinitions; attributes?: FieldDefinitions } | undefined): ComponentFields {
  const names = new Set<string>();
  const read = (definitions: FieldDefinitions | undefined, kind: FieldDefinition['kind']): FieldDefinitions => {
    if (definitions === undefined) return Object.freeze({});
    if (!definitions || typeof definitions !== 'object' || Array.isArray(definitions)) throw new TypeError(`${kind} definitions must be an object`);
    const result: Record<string, FieldDefinition> = Object.create(null);
    for (const [name, definition] of Object.entries(definitions)) {
      if (!/^[A-Za-z_]\w*$/.test(name) || ['__proto__', 'constructor', 'prototype', 'src', 'ready', 'path', 'index'].includes(name.toLowerCase())) {
        throw new TypeError(`Reserved or invalid component input: ${name}`);
      }
      if (names.has(name.toLowerCase())) throw new TypeError(`Duplicate component input: ${name}`);
      if (!definition || definition[fieldBrand] !== true || definition.kind !== kind) throw new TypeError(`Invalid ${kind} definition: ${name}`);
      names.add(name.toLowerCase());
      result[name] = definition;
    }
    return Object.freeze(result);
  };
  return Object.freeze({ properties: read(behavior?.properties, 'property'), attributes: read(behavior?.attributes, 'attribute') });
}

export function initialValue(definition: FieldDefinition): unknown {
  const value = definition.defaultValue;
  return value !== null && typeof value === 'object' ? structuredClone(value) : value;
}

export function parseAttribute(definition: FieldDefinition, value: string | null): unknown {
  if (value === null) return definition.defaultValue;
  if (typeof definition.defaultValue === 'boolean') return true;
  if (typeof definition.defaultValue === 'number') {
    const number = value.trim() ? Number(value) : NaN;
    if (!Number.isFinite(number)) throw new TypeError(`Invalid numeric attribute: ${JSON.stringify(value)}`);
    return number;
  }
  return value;
}

export function serializeAttribute(definition: FieldDefinition, value: unknown): string | null {
  if (value === undefined) value = definition.defaultValue;
  if (!isScalar(value) || typeof value !== typeof definition.defaultValue) {
    throw new TypeError(`Input requires ${typeof definition.defaultValue}`);
  }
  return typeof value === 'boolean' ? value ? '' : null : String(value);
}
