import type { Scope } from '../../lifecycle/scope.js';
import { Signal } from '../../state/signal.js';

export interface EventDeclaration {
  readonly name: string;
  readonly options: AddEventListenerOptions;
}

/** 点后仅接受原生监听选项；不把条件、参数或业务控制变成修饰符语言。 */
export function parseEventDeclaration(attribute: string): EventDeclaration {
  if (attribute !== attribute.trim() || !attribute.startsWith('ns-on-')) throw new Error(`Invalid event directive: ${attribute}`);
  const [name, ...modifiers] = attribute.slice(6).split('.');
  if (!/^[a-z][a-z0-9:_-]*$/.test(name)) throw new Error(`Invalid event binding name: ${name}`);
  const options = { capture: false, once: false, passive: false };
  const seen = new Set<string>();
  for (const modifier of modifiers) {
    if (!Object.hasOwn(options, modifier) || seen.has(modifier)) throw new Error(`Invalid event option: ${attribute}`);
    seen.add(modifier);
    options[modifier as keyof typeof options] = true;
  }
  return { name, options };
}

/** 新事件协议：原生 Event、普通函数调用、不改变默认行为，始终观察返回任务。 */
export function bindHandler(
  element: Element,
  declaration: EventDeclaration,
  handler: (event: Event) => unknown,
  scope: Scope,
  onError: (error: unknown) => void,
): void {
  if (typeof handler !== 'function') throw new TypeError('Event handler expression must produce a function');
  const listener = (event: Event) => {
    try {
      const result: unknown = Signal.subtle.untrack(() => Reflect.apply(handler, undefined, [event]));
      if (result !== null && (typeof result === 'object' || typeof result === 'function')) {
        void Promise.resolve(result).catch(onError);
      }
    } catch (error) { onError(error); }
  };
  element.addEventListener(declaration.name, listener, declaration.options);
  scope.add(() => element.removeEventListener(declaration.name, listener, declaration.options));
}
